bool estimateLayoutTypedBytes(
        const DRW_Layout& layout, std::size_t& estimate,
        std::size_t& itemCount) noexcept {
    estimate = sizeof(DRW_Layout);
    itemCount = layout.viewportHandles.size();
    if (itemCount > DRW_Layout::kMaxViewportCount
        || !addTableEntryRetainedBytes(layout, estimate)
        || !addStringPayloadBytes(layout.pageSetupName, estimate)
        || !addStringPayloadBytes(layout.printerConfig, estimate)
        || !addStringPayloadBytes(layout.paperSize, estimate)
        || !addStringPayloadBytes(layout.plotViewName, estimate)
        || !addStringPayloadBytes(layout.currentStyleSheet, estimate)
        || !addVectorPayloadBytes(layout.viewportHandles, estimate))
        return false;
    return estimate <= kMaxAdapterBasicTableRetainedBytes;
}

bool estimatePlotSettingsTypedBytes(
        const DRW_PlotSettings& settings,
        std::size_t& estimate) noexcept {
    estimate = sizeof(DRW_PlotSettings);
    return addTableEntryRetainedBytes(settings, estimate)
        && addStringPayloadBytes(settings.pageSetupName, estimate)
        && addStringPayloadBytes(settings.printerConfig, estimate)
        && addStringPayloadBytes(settings.paperSize, estimate)
        && addStringPayloadBytes(settings.plotViewName, estimate)
        && addStringPayloadBytes(settings.currentStyleSheet, estimate)
        && addVectorPayloadBytes(settings.dwgEedAppIdReferences, estimate)
        && addVectorPayloadBytes(settings.dwgEedLayerReferences, estimate)
        && addAssociativeSlotBytes(1u, 2u * sizeof(void*), estimate)
        && estimate <= dx_iface::PlotSettingsCaptureMaxRetainedBytes;
}

bool estimateGeoDataTypedBytes(
        const DRW_GeoData& data, std::size_t& estimate) noexcept {
    using GeoDataMapValue =
        std::pair<const dx_data::GeoDataKey, DRW_GeoData>;
    using GeoDataSourceRoleValue = std::pair<const dx_data::GeoDataKey,
        std::pair<std::int32_t, std::uint32_t>>;
    estimate = sizeof(GeoDataMapValue) + sizeof(GeoDataSourceRoleValue)
        + 8u * sizeof(void*);
    if (data.m_points.size() > DRW_GeoData::kMaxMeshItems
        || data.m_faces.size() > DRW_GeoData::kMaxMeshItems
        || !addTableEntryRetainedBytes(data, estimate)
        || !addVectorPayloadBytes(data.m_points, estimate)
        || !addVectorPayloadBytes(data.m_faces, estimate)
        || !addStringPayloadBytes(data.m_coordinateSystemDefinition, estimate)
        || !addStringPayloadBytes(data.m_geoRssTag, estimate)
        || !addStringPayloadBytes(data.m_observationFromTag, estimate)
        || !addStringPayloadBytes(data.m_observationToTag, estimate)
        || !addStringPayloadBytes(data.m_observationCoverageTag, estimate)
        || !addStringPayloadBytes(
               data.m_legacy.m_coordinateSystemDescription, estimate)
        || !addStringPayloadBytes(data.m_legacy.m_coordinateSystemDatum,
                                  estimate))
        return false;
    return estimate <= kMaxAdapterGeoDataRetainedBytes;
}

bool estimateRasterVariablesTypedBytes(
        const DRW_RasterVariables& data, std::size_t& estimate) noexcept {
    using RasterVariablesMapValue = std::pair<
        const dx_data::RasterVariablesKey, DRW_RasterVariables>;
    estimate = sizeof(RasterVariablesMapValue) + 4u * sizeof(void*);
    return addTableEntryRetainedBytes(data, estimate)
        && estimate <= kMaxAdapterRasterVariablesRetainedBytes;
}

