bool estimateModelDocViewStyleTypedBytes(
        const DRW_SectionViewStyle& style, std::size_t& estimate,
        std::size_t& itemCount) noexcept {
    estimate = sizeof(DRW_SectionViewStyle);
    itemCount = style.m_hatchAngles.size();
    return itemCount <= DRW_SectionViewStyle::kMaxHatchAngles
        && itemCount <= kMaxAdapterModelDocViewStyleTypedItems
        && addTableEntryRetainedBytes(style, estimate)
        && addStringPayloadBytes(style.m_modelDoc.m_description, estimate)
        && addStringPayloadBytes(style.m_modelDoc.m_displayName, estimate)
        && addStringPayloadBytes(style.m_identifierExcludeCharacters, estimate)
        && addStringPayloadBytes(style.m_viewLabelPattern, estimate)
        && addStringPayloadBytes(style.m_hatchPattern, estimate)
        && addVectorPayloadBytes(style.m_hatchAngles, estimate);
}

void failModelDocViewStyleTypedCapture(
        dx_data& data, bool resourceLimit) noexcept {
    if (resourceLimit)
        data.modelDocViewStyleTypedResourceLimitExceeded = true;
    else
        data.modelDocViewStyleTypedCaptureFailed = true;
    dx_modelDocViewStyleImportReceipt& receipt =
        data.modelDocViewStyleImport;
    if (receipt.generation == data.importGeneration) {
        if (resourceLimit)
            receipt.typedResourceLimitExceeded = true;
        else
            receipt.typedCaptureFailed = true;
    }
}

template <typename Record, typename Estimate>
void retainModelDocViewStyleTyped(
        dx_data* data, std::list<Record>& destination,
        const Record& record, Estimate estimate) {
    if (data == nullptr || data->modelDocViewStyleTypedCaptureFailed
        || data->modelDocViewStyleTypedResourceLimitExceeded)
        return;
    if (data->sourceFormat == dx_source_format::DXF
        && data->importGeneration != 0u
        && data->modelDocViewStyleImport.generation
            != data->importGeneration) {
        failModelDocViewStyleTypedCapture(*data, false);
        return;
    }
    std::size_t retainedBytes = 0u;
    std::size_t itemCount = 0u;
    if (!estimate(record, retainedBytes, itemCount)
        || !addAssociativeSlotBytes(2u, sizeof(void*), retainedBytes)) {
        failModelDocViewStyleTypedCapture(*data, true);
        return;
    }
    if (data->modelDocViewStyleTypedRetainedRecords
            >= kMaxAdapterModelDocViewStyleRecords
        || data->modelDocViewStyleTypedRetainedItems
            > kMaxAdapterModelDocViewStyleTypedItems
        || itemCount > kMaxAdapterModelDocViewStyleTypedItems
            - data->modelDocViewStyleTypedRetainedItems
        || data->modelDocViewStyleTypedRetainedBytes
            > kMaxAdapterModelDocViewStyleRetainedBytes
        || retainedBytes > kMaxAdapterModelDocViewStyleRetainedBytes
            - data->modelDocViewStyleTypedRetainedBytes) {
        failModelDocViewStyleTypedCapture(*data, true);
        return;
    }
    try {
        destination.push_back(record);
    } catch (...) {
        failModelDocViewStyleTypedCapture(*data, false);
        return;
    }
    ++data->modelDocViewStyleTypedRetainedRecords;
    data->modelDocViewStyleTypedRetainedItems += itemCount;
    data->modelDocViewStyleTypedRetainedBytes += retainedBytes;
}

bool estimateFieldCadValueBytes(
        const DRW_CadValue& value, std::size_t& estimate) noexcept {
    return estimateTableEntryVariantBytes(&value.m_value, estimate)
        && addStringPayloadBytes(value.m_formatString, estimate)
        && addStringPayloadBytes(value.m_valueString, estimate)
        && addVectorPayloadBytes(value.m_rawData, estimate);
}

bool estimateFieldTypedBytes(
        const DRW_Field& field, std::size_t& estimate,
        std::size_t& itemCount) noexcept {
    estimate = sizeof(DRW_Field);
    itemCount = 0u;
    if (field.m_childHandles.size() > DRW_Field::kMaxItems
        || field.m_objectHandles.size() > DRW_Field::kMaxItems
        || field.m_childValues.size() > DRW_Field::kMaxItems)
        return false;
    const auto addItems = [&itemCount](std::size_t count) {
        if (itemCount > kMaxAdapterFieldTypedItems
            || count > kMaxAdapterFieldTypedItems - itemCount)
            return false;
        itemCount += count;
        return true;
    };
    if (!addTableEntryRetainedBytes(field, estimate)
        || !addStringPayloadBytes(field.m_evaluatorId, estimate)
        || !addStringPayloadBytes(field.m_fieldCode, estimate)
        || !addStringPayloadBytes(field.m_formatString, estimate)
        || !addStringPayloadBytes(field.m_evaluationErrorMessage, estimate)
        || !addStringPayloadBytes(field.m_valueString, estimate)
        || !addVectorPayloadBytes(field.m_childHandles, estimate)
        || !addVectorPayloadBytes(field.m_objectHandles, estimate)
        || !addVectorPayloadBytes(field.m_childValues, estimate)
        || !estimateFieldCadValueBytes(field.m_value, estimate)
        || !addItems(field.m_childHandles.size())
        || !addItems(field.m_objectHandles.size())
        || !addItems(field.m_childValues.size()))
        return false;
    for (const DRW_Field::ChildValue& child : field.m_childValues) {
        if (!addStringPayloadBytes(child.m_key, estimate)
            || !estimateFieldCadValueBytes(child.m_value, estimate))
            return false;
    }
    return true;
}

bool estimateFieldListTypedBytes(
        const DRW_FieldList& fieldList, std::size_t& estimate,
        std::size_t& itemCount) noexcept {
    estimate = sizeof(DRW_FieldList);
    itemCount = fieldList.m_fieldHandles.size();
    return itemCount <= DRW_Field::kMaxItems
        && addTableEntryRetainedBytes(fieldList, estimate)
        && addVectorPayloadBytes(fieldList.m_fieldHandles, estimate);
}

bool estimateDataLinkTypedBytes(
        const DRW_DataLink& dataLink,
        std::size_t& estimate, std::size_t& itemCount) noexcept {
    estimate = sizeof(DRW_DataLink);
    itemCount = dataLink.m_customData.size();
    if (itemCount > kMaxAdapterDataLinkItems
        || !addTableEntryRetainedBytes(dataLink, estimate)
        || !addStringPayloadBytes(dataLink.m_dataAdapter, estimate)
        || !addStringPayloadBytes(dataLink.m_description, estimate)
        || !addStringPayloadBytes(dataLink.m_tooltip, estimate)
        || !addStringPayloadBytes(dataLink.m_connectionString, estimate)
        || !addStringPayloadBytes(dataLink.m_updateStatus, estimate)
        || !addAssociativeSlotBytes(dataLink.m_customData.size(),
                sizeof(DRW_DataLinkCustomData), estimate))
        return false;

    for (const DRW_DataLinkCustomData& customData : dataLink.m_customData) {
        if (!addStringPayloadBytes(customData.m_text, estimate))
            return false;
    }
    return estimate <= kMaxAdapterDataLinkRetainedBytes;
}

bool estimatePointCloudDefinitionBytes(
        const DRW_PointCloudDef& value, std::size_t& estimate,
        std::size_t& itemCount) noexcept {
    const int kind = static_cast<int>(value.m_kind);
    estimate = sizeof(DRW_PointCloudDef);
    itemCount = value.reactorHandles.size();
    if (kind < static_cast<int>(DRW_PointCloudDef::Definition)
        || kind > static_cast<int>(DRW_PointCloudDef::ReactorEx)
        || value.tType != DRW::POINTCLOUDDEF
        || value.m_classVersion < 0
        || value.m_classVersion > DRW_PointCloudDef::kMaxClassVersion
        || itemCount > kMaxAdapterPointCloudObjectItems
        || !addTableEntryRetainedBytes(value, estimate))
        return false;
    const auto addItems = [&itemCount](std::size_t count) noexcept {
        if (itemCount > kMaxAdapterPointCloudObjectItems
            || count > kMaxAdapterPointCloudObjectItems - itemCount)
            return false;
        itemCount += count;
        return true;
    };
    if (!addItems(value.extData.size()) || !addItems(value.appData.size()))
        return false;
    for (const auto& group : value.appData) {
        if (!addItems(group.size()))
            return false;
    }
    if (!addStringPayloadBytes(value.m_sourceFilename, estimate))
        return false;
    return estimate <= kMaxAdapterPointCloudObjectRetainedBytes;
}

bool normalizePointCloudDefinitionReactors(DRW_PointCloudDef& value) noexcept {
    if (value.appData.empty())
        return true;
    if (value.appData.size() != 1u)
        return false;
    const auto& group = value.appData.front();
    if (group.size() < 2u || group.front().code() != 102
        || group.front().type() != DRW_Variant::STRING
        || group.front().content.s == nullptr
        || *group.front().content.s != "ACAD_REACTORS"
        || group.back().code() != 102
        || group.back().type() != DRW_Variant::STRING
        || group.back().content.s == nullptr
        || *group.back().content.s != "}")
        return false;

    std::vector<std::uint32_t> reactors;
    try {
        reactors.reserve(group.size() - 2u);
        for (auto item = std::next(group.begin());
             item != std::prev(group.end()); ++item) {
            if (item->code() != 330 || item->type() != DRW_Variant::STRING
                || item->content.s == nullptr || item->content.s->empty())
                return false;
            std::uint32_t handle = 0u;
            const std::string& text = *item->content.s;
            const auto parsed = std::from_chars(
                text.data(), text.data() + text.size(), handle, 16);
            if (parsed.ec != std::errc{}
                || parsed.ptr != text.data() + text.size()
                || handle == 0u || handle == DRW::NoHandle)
                return false;
            reactors.push_back(handle);
        }
    } catch (...) {
        return false;
    }
    if (reactors.size()
            > static_cast<std::size_t>(
                (std::numeric_limits<std::int32_t>::max)())
        || reactors != value.reactorHandles)
        return false;
    value.setDwgCommonObjectState(
        static_cast<std::int32_t>(reactors.size()),
        value.extensionDictionaryFlag(), value.hasDataStorageBinaryData());
    value.appData.clear();
    return true;
}

bool pointCloudDefinitionModelEqual(const DRW_PointCloudDef& left,
                                    const DRW_PointCloudDef& right,
                                    DRW::Version version) noexcept {
    const auto sameCoord = [](const DRW_Coord& a, const DRW_Coord& b) {
        return std::memcmp(&a.x, &b.x, sizeof(a.x)) == 0
            && std::memcmp(&a.y, &b.y, sizeof(a.y)) == 0
            && std::memcmp(&a.z, &b.z, sizeof(a.z)) == 0;
    };
    return standardDwgCommonEqual(left, right, version, true)
        && left.m_kind == right.m_kind
        && left.m_classVersion == right.m_classVersion
        && left.m_sourceFilename == right.m_sourceFilename
        && left.m_isLoaded == right.m_isLoaded
        && left.m_pointCount == right.m_pointCount
        && sameCoord(left.m_extentsMin, right.m_extentsMin)
        && sameCoord(left.m_extentsMax, right.m_extentsMax);
}

bool pointCloudRawDxfObjectMatchesPhysical(
        const DRW_RawDxfObject& raw,
        const DRW_DxfObjectPhysicalSource& physical) noexcept {
    if (physical.status != DRW_DxfObjectPhysicalSource::Status::Complete
        || physical.name != raw.name || physical.version != raw.m_version
        || raw.hasRawValues == physical.binary
        || physical.marker.endOffset <= physical.marker.beginOffset
        || physical.endMarker.endOffset <= physical.endMarker.beginOffset
        || physical.endMarker.beginOffset < physical.marker.endOffset)
        return false;
    std::size_t groupIndex = 0u;
    std::size_t previousOrdinal = physical.marker.ordinal;
    std::size_t previousOffset = physical.marker.endOffset;
    for (const DRW_DxfObjectPhysicalSource::Field& field : physical.fields) {
        const DRW_DxfPhysicalRecordSpan& span = field.span;
        if (span.beginOffset < previousOffset || span.endOffset <= span.beginOffset
            || span.ordinal <= previousOrdinal)
            return false;
        previousOrdinal = span.ordinal;
        previousOffset = span.endOffset;
        if (span.ignoredComment)
            continue;
        if (groupIndex >= raw.groups.size()
            || raw.groups[groupIndex].code() != field.code)
            return false;
        ++groupIndex;
    }
    return groupIndex == raw.groups.size()
        && physical.endMarker.ordinal > previousOrdinal
        && physical.endMarker.beginOffset >= previousOffset;
}

bool pointCloudDefinitionRawProjectsToModel(
        const DRW_RawDxfObject& raw, const DRW_PointCloudDef& definition,
        DRW::Version version) noexcept {
    if (version < DRW::AC1027 || version > DRW::AC1032
        || raw.m_version != version
        || raw.groups.size() != raw.rawValues.size()
        || definition.handle == 0u || definition.handle == DRW::NoHandle
        || definition.parentHandle == 0u
        || definition.parentHandle == DRW::NoHandle
        || definition.m_classVersion < 0
        || definition.m_classVersion
            > DRW_PointCloudDef::kMaxClassVersion)
        return false;

    const bool classicDefinition =
        definition.m_kind == DRW_PointCloudDef::Definition
        && (dx_block_membership::equal(raw.name, "POINTCLOUDDEFINITION")
            || dx_block_membership::equal(raw.name,
                                           "ACDBPOINTCLOUDDEFINITION"));
    const bool extendedDefinition =
        definition.m_kind == DRW_PointCloudDef::DefinitionEx
        && (dx_block_membership::equal(
                raw.name, "POINTCLOUDDEFINITIONEX")
            || dx_block_membership::equal(raw.name,
                                           "ACDBPOINTCLOUDDEFEX"));
    const bool classicReactor =
        definition.m_kind == DRW_PointCloudDef::Reactor
        && (dx_block_membership::equal(raw.name, "POINTCLOUDDEFREACTOR")
            || dx_block_membership::equal(
                raw.name, "ACDBPOINTCLOUDDEFREACTOR"));
    const bool extendedReactor =
        definition.m_kind == DRW_PointCloudDef::ReactorEx
        && (dx_block_membership::equal(raw.name,
                                       "POINTCLOUDDEFREACTOREX")
            || dx_block_membership::equal(
                raw.name, "ACDBPOINTCLOUDDEFREACTOREX"));
    const bool isDefinition = classicDefinition || extendedDefinition;
    const char* subclassName = isDefinition
        ? (classicDefinition ? "AcDbPointCloudDef" : "AcDbPointCloudDefEx")
        : classicReactor ? "AcDbPointCloudDefReactor"
        : extendedReactor ? "AcDbPointCloudDefReactorEx" : nullptr;
    if (subclassName == nullptr) {
        return false;
    }
    if (isDefinition
        && (definition.m_sourceFilename.empty()
            || definition.m_pointCount > DRW_PointCloudDef::kMaxPointCount
            || !std::isfinite(definition.m_extentsMin.x)
            || !std::isfinite(definition.m_extentsMin.y)
            || !std::isfinite(definition.m_extentsMin.z)
            || !std::isfinite(definition.m_extentsMax.x)
            || !std::isfinite(definition.m_extentsMax.y)
            || !std::isfinite(definition.m_extentsMax.z)))
        return false;
    const auto isText = [](const DRW_Variant& field) {
        return field.type() == DRW_Variant::STRING
            && field.content.s != nullptr;
    };
    const auto parseHandle = [](const DRW_Variant& field,
                                std::uint32_t expected) {
        if (field.type() != DRW_Variant::STRING
            || field.content.s == nullptr || field.content.s->empty()
            || expected == 0u || expected == DRW::NoHandle)
            return false;
        const std::string& text = *field.content.s;
        std::uint64_t actual = 0u;
        const auto parsed = std::from_chars(
            text.data(), text.data() + text.size(), actual, 16);
        return parsed.ec == std::errc{}
            && parsed.ptr == text.data() + text.size()
            && actual == expected;
    };
    const auto sameReal = [](double left, double right) {
        return std::memcmp(&left, &right, sizeof(left)) == 0;
    };
    const auto at = [&raw](std::size_t index, int code) {
        return index < raw.groups.size()
            && raw.groups[index].code() == code;
    };

    std::size_t index = 0u;
    if (!at(index, 5)
        || !parseHandle(raw.groups[index], definition.handle))
        return false;
    ++index;

    std::size_t reactorCount = 0u;
    if (at(index, 102)) {
        if (!isText(raw.groups[index])
            || *raw.groups[index].content.s != "{ACAD_REACTORS"
            || !isDefinition
            || definition.reactorHandles.empty()
            || definition.reactorCount()
                != static_cast<std::int32_t>(definition.reactorHandles.size()))
            return false;
        ++index;
        while (at(index, 330)) {
            if (reactorCount >= definition.reactorHandles.size()
                || !parseHandle(raw.groups[index],
                                definition.reactorHandles[reactorCount]))
                return false;
            ++reactorCount;
            ++index;
        }
        if (!at(index, 102) || !isText(raw.groups[index])
            || *raw.groups[index].content.s != "}")
            return false;
        ++index;
    }
    if (reactorCount != definition.reactorHandles.size()
        || !at(index, 330)
        || !parseHandle(raw.groups[index], definition.parentHandle))
        return false;
    ++index;
    if (!at(index, 100) || !isText(raw.groups[index])
        || *raw.groups[index].content.s != subclassName)
        return false;
    ++index;
    if (!at(index, 90)
        || raw.groups[index].type() != DRW_Variant::INTEGER
        || raw.groups[index].i_val() != definition.m_classVersion)
        return false;
    ++index;

    if (isDefinition) {
        if (!at(index, 1) || !isText(raw.groups[index])
            || *raw.groups[index].content.s != definition.m_sourceFilename)
            return false;
        ++index;
        if (!at(index, 280)
            || raw.groups[index].type() != DRW_Variant::INTEGER
            || (raw.groups[index].i_val() != 0
                && raw.groups[index].i_val() != 1)
            || definition.m_isLoaded
                != (raw.groups[index].i_val() != 0))
            return false;
        ++index;
        if (!at(index, 160)
            || raw.groups[index].type() != DRW_Variant::INTEGER64
            || raw.groups[index].i64_val() < 0
            || static_cast<std::uint64_t>(raw.groups[index].i64_val())
                != definition.m_pointCount)
            return false;
        ++index;
        const std::array<std::pair<int, double>, 6u> coordinates{{
            {10, definition.m_extentsMin.x},
            {20, definition.m_extentsMin.y},
            {30, definition.m_extentsMin.z},
            {11, definition.m_extentsMax.x},
            {21, definition.m_extentsMax.y},
            {31, definition.m_extentsMax.z}}};
        for (const auto& coordinate : coordinates) {
            if (!at(index, coordinate.first)
                || raw.groups[index].type() != DRW_Variant::DOUBLE
                || !std::isfinite(raw.groups[index].content.d)
                || !sameReal(raw.groups[index].content.d,
                             coordinate.second))
                return false;
            ++index;
        }
    }
    return index == raw.groups.size();
}

bool pointCloudExModelEqual(const DRW_PointCloudEx& left,
                            const DRW_PointCloudEx& right,
                            DRW::Version version) noexcept {
    const auto equalVariant = [version](const DRW_Variant& a,
                                        const DRW_Variant& b) {
        return standardDwgVariantEqual(a, b, version);
    };
    const auto sameReal = [](double a, double b) {
        return std::memcmp(&a, &b, sizeof(a)) == 0;
    };
    const auto sameCoord = [&sameReal](const DRW_Coord& a,
                                       const DRW_Coord& b) {
        return sameReal(a.x, b.x) && sameReal(a.y, b.y)
            && sameReal(a.z, b.z);
    };
    if (!dxfAttdef::Decoder::sameEntityModel(left, right, equalVariant)
        || std::tie(left.classVersion, left.isLocked, left.definitionHandle,
                    left.reactorHandle, left.name, left.showIntensity,
                    left.showCropping, left.croppingCount, left.unknownInt0,
                    left.unknownInt1, left.stylizationType,
                    left.intensityColorScheme, left.currentColorScheme,
                    left.classificationColorScheme, left.intensityMin,
                    left.intensityMax, left.intensityOutOfRangeBehavior,
                    left.elevationOutOfRangeBehavior,
                    left.elevationApplyToFixedRange,
                    left.intensityAsGradient, left.elevationAsGradient)
            != std::tie(right.classVersion, right.isLocked,
                        right.definitionHandle, right.reactorHandle,
                        right.name, right.showIntensity, right.showCropping,
                        right.croppingCount, right.unknownInt0,
                        right.unknownInt1, right.stylizationType,
                        right.intensityColorScheme, right.currentColorScheme,
                        right.classificationColorScheme, right.intensityMin,
                        right.intensityMax,
                        right.intensityOutOfRangeBehavior,
                        right.elevationOutOfRangeBehavior,
                        right.elevationApplyToFixedRange,
                        right.intensityAsGradient, right.elevationAsGradient)
        || left.croppings.size() != right.croppings.size()
        || !sameCoord(left.extentsMin, right.extentsMin)
        || !sameCoord(left.extentsMax, right.extentsMax)
        || !sameCoord(left.ucsOrigin, right.ucsOrigin)
        || !sameCoord(left.ucsXDirection, right.ucsXDirection)
        || !sameCoord(left.ucsYDirection, right.ucsYDirection)
        || !sameCoord(left.ucsZDirection, right.ucsZDirection)
        || !sameReal(left.elevationMin, right.elevationMin)
        || !sameReal(left.elevationMax, right.elevationMax)
        || !sameReal(left.intensityMin, right.intensityMin)
        || !sameReal(left.intensityMax, right.intensityMax))
        return false;
    for (std::size_t i = 0u; i < left.croppings.size(); ++i) {
        const DRW_PointCloudExCropping& a = left.croppings[i];
        const DRW_PointCloudExCropping& b = right.croppings[i];
        if (std::tie(a.type, a.isInside, a.isInverted, a.pointCount)
                != std::tie(b.type, b.isInside, b.isInverted, b.pointCount)
            || a.points.size() != b.points.size()
            || !sameCoord(a.cropPlane, b.cropPlane)
            || !sameCoord(a.cropXDirection, b.cropXDirection)
            || !sameCoord(a.cropYDirection, b.cropYDirection))
            return false;
        for (std::size_t point = 0u; point < a.points.size(); ++point) {
            if (!sameCoord(a.points[point], b.points[point]))
                return false;
        }
    }
    return true;
}

bool pointCloudPhysicalRecordValid(
        const DRW_DxfPhysicalEntitySource& record, const char* entityName,
        DRW::Version version, bool binary) noexcept {
    if (entityName == nullptr
        || !dx_block_membership::equal(record.name, entityName)
        || record.marker.ignoredComment
        || record.marker.beginOffset >= record.marker.endOffset
        || record.marker.ordinal >= record.endOrdinal
        || record.endOffset < record.marker.endOffset
        || record.groups.size() != record.rawValues.size()
        || record.groups.size() != record.spans.size())
        return false;
    std::size_t ordinal = record.marker.ordinal;
    std::size_t offset = record.marker.endOffset;
    for (std::size_t i = 0u; i < record.groups.size(); ++i) {
        const DRW_Variant& field = record.groups[i];
        const DRW_DxfPhysicalRecordSpan& span = record.spans[i];
        if (ordinal == (std::numeric_limits<std::size_t>::max)()
            || span.ordinal != ordinal + 1u
            || span.beginOffset < offset || span.beginOffset >= span.endOffset
            || (span.ignoredComment && field.code() != 999)
            || field.code() == 0
            || (binary && !record.rawValues[i].empty()))
            return false;
        if (field.type() == DRW_Variant::STRING) {
            if (!field.content.s)
                return false;
        } else if (field.type() != DRW_Variant::INTEGER
                   && field.type() != DRW_Variant::INTEGER64
                   && field.type() != DRW_Variant::DOUBLE) {
            return false;
        }
        ordinal = span.ordinal;
        offset = span.endOffset;
    }
    return ordinal != (std::numeric_limits<std::size_t>::max)()
        && ordinal + 1u == record.endOrdinal
        && offset <= record.endOffset
        && version >= DRW::AC1021 && version <= DRW::AC1032;
}

bool pointCloudExPhysicalRecordValid(
        const DRW_DxfPhysicalEntitySource& record,
        DRW::Version version, bool binary) noexcept {
    return pointCloudPhysicalRecordValid(
        record, "POINTCLOUDEX", version, binary);
}

bool pointCloudModelEqual(const DRW_PointCloud& left,
                          const DRW_PointCloud& right,
                          DRW::Version version) noexcept {
    const auto equalVariant = [version](const DRW_Variant& a,
                                        const DRW_Variant& b) {
        return standardDwgVariantEqual(a, b, version);
    };
    const auto sameReal = [](double a, double b) {
        return std::memcmp(&a, &b, sizeof(a)) == 0;
    };
    const auto sameCoord = [&sameReal](const DRW_Coord& a,
                                       const DRW_Coord& b) {
        return sameReal(a.x, b.x) && sameReal(a.y, b.y)
            && sameReal(a.z, b.z);
    };
    if (!dxfAttdef::Decoder::sameEntityModel(left, right, equalVariant)
        || std::tie(left.classVersion, left.savedFilename,
                    left.sourceFileCount, left.sourceFiles, left.pointCount,
                    left.ucsName, left.definitionHandle, left.reactorHandle,
                    left.showIntensity, left.intensityScheme,
                    left.showClipping, left.clippingCount)
            != std::tie(right.classVersion, right.savedFilename,
                        right.sourceFileCount, right.sourceFiles,
                        right.pointCount, right.ucsName,
                        right.definitionHandle, right.reactorHandle,
                        right.showIntensity, right.intensityScheme,
                        right.showClipping, right.clippingCount)
        || left.clippings.size() != right.clippings.size()
        || !sameCoord(left.origin, right.origin)
        || !sameCoord(left.extentsMin, right.extentsMin)
        || !sameCoord(left.extentsMax, right.extentsMax)
        || !sameCoord(left.ucsOrigin, right.ucsOrigin)
        || !sameCoord(left.ucsXDirection, right.ucsXDirection)
        || !sameCoord(left.ucsYDirection, right.ucsYDirection)
        || !sameCoord(left.ucsZDirection, right.ucsZDirection)
        || !sameReal(left.intensityStyle.minIntensity,
                     right.intensityStyle.minIntensity)
        || !sameReal(left.intensityStyle.maxIntensity,
                     right.intensityStyle.maxIntensity)
        || !sameReal(left.intensityStyle.lowThreshold,
                     right.intensityStyle.lowThreshold)
        || !sameReal(left.intensityStyle.highThreshold,
                     right.intensityStyle.highThreshold))
        return false;
    for (std::size_t i = 0u; i < left.clippings.size(); ++i) {
        const DRW_PointCloudClipping& a = left.clippings[i];
        const DRW_PointCloudClipping& b = right.clippings[i];
        if (std::tie(a.isInverted, a.type, a.vertexCount)
                != std::tie(b.isInverted, b.type, b.vertexCount)
            || a.vertices.size() != b.vertices.size()
            || !sameReal(a.zMin, b.zMin) || !sameReal(a.zMax, b.zMax))
            return false;
        for (std::size_t vertex = 0u; vertex < a.vertices.size(); ++vertex) {
            if (!sameCoord(a.vertices[vertex], b.vertices[vertex]))
                return false;
        }
    }
    return true;
}

bool pointCloudSourceFieldProfileComplete(
        const DRW_DxfPhysicalEntitySource& record,
        const DRW_PointCloud& cloud, DRW::Version version,
        bool binary, bool allowDefinitionReferences = false) noexcept {
    if (!pointCloudPhysicalRecordValid(record, "POINTCLOUD", version, binary)
        || version < DRW::AC1027
        || (allowDefinitionReferences
            ? (cloud.definitionHandle == 0u
                || cloud.definitionHandle == DRW::NoHandle
                || cloud.reactorHandle == 0u
                || cloud.reactorHandle == DRW::NoHandle)
            : (cloud.definitionHandle != 0u || cloud.reactorHandle != 0u))
        || cloud.showIntensity
        || cloud.showClipping || cloud.clippingCount != 0
        || !cloud.clippings.empty()
        || cloud.space != DRW::ModelSpace
        || cloud.parentHandle != DRW::DxfModelSpaceBlockRecordHandle
        || cloud.classVersion > std::numeric_limits<std::uint16_t>::max()
        || cloud.sourceFileCount < 0
        || cloud.sourceFileCount > static_cast<int>(DRW_PointCloud::kMaxItems)
        || cloud.sourceFiles.size()
            != static_cast<std::size_t>(cloud.sourceFileCount)
        || cloud.pointCount > static_cast<std::uint64_t>(
               std::numeric_limits<std::int32_t>::max())
        || cloud.intensityScheme < 0
        || cloud.intensityScheme
            > std::numeric_limits<std::uint16_t>::max())
        return false;
    const auto finite = [](const DRW_Coord& value) {
        return std::isfinite(value.x) && std::isfinite(value.y)
            && std::isfinite(value.z);
    };
    if (!finite(cloud.origin) || !finite(cloud.extentsMin)
        || !finite(cloud.extentsMax) || !finite(cloud.ucsOrigin)
        || !finite(cloud.ucsXDirection) || !finite(cloud.ucsYDirection)
        || !finite(cloud.ucsZDirection)
        || !std::isfinite(cloud.intensityStyle.minIntensity)
        || !std::isfinite(cloud.intensityStyle.maxIntensity)
        || !std::isfinite(cloud.intensityStyle.lowThreshold)
        || !std::isfinite(cloud.intensityStyle.highThreshold))
        return false;

    enum class Scope : std::uint8_t { Header, Entity, PointCloud };
    Scope scope = Scope::Header;
    std::size_t subclassCount = 0u;
    std::size_t sourceFileIndex = 0u;
    bool entityHandleMatched = false;
    bool entityOwnerMatched = false;
    std::size_t classVersionCount = 0u;
    std::size_t sourceCountCount = 0u;
    std::size_t pointCountCount = 0u;
    std::size_t definitionReferenceCount = 0u;
    std::size_t reactorReferenceCount = 0u;
    std::array<std::size_t, 1072u> commonCounts{};
    std::array<std::size_t, 1072u> bodyCounts{};
    const auto isText = [](const DRW_Variant& field) {
        return field.type() == DRW_Variant::STRING
            && field.content.s != nullptr;
    };
    const auto isInt = [](const DRW_Variant& field) {
        return field.type() == DRW_Variant::INTEGER;
    };
    const auto isReal = [](const DRW_Variant& field) {
        return field.type() == DRW_Variant::DOUBLE
            && std::isfinite(field.content.d);
    };
    const auto sameReal = [](double left, double right) {
        return std::memcmp(&left, &right, sizeof(left)) == 0;
    };
    const auto handleMatches = [](const DRW_Variant& field,
                                  std::uint32_t expected,
                                  bool requireNonzero) {
        if (field.type() != DRW_Variant::STRING || field.content.s == nullptr
            || field.content.s->empty())
            return false;
        const std::string& text = *field.content.s;
        std::uint64_t parsedHandle = 0u;
        const auto parsed = std::from_chars(
            text.data(), text.data() + text.size(), parsedHandle, 16);
        return parsed.ec == std::errc{}
            && parsed.ptr == text.data() + text.size()
            && parsedHandle <= (std::numeric_limits<std::uint32_t>::max)()
            && parsedHandle == expected
            && (!requireNonzero || (expected != 0u
                                    && expected != DRW::NoHandle));
    };
    const auto increment = [](std::array<std::size_t, 1072u>& counts,
                              int code) {
        if (code < 0 || static_cast<std::size_t>(code) >= counts.size()
            || counts[static_cast<std::size_t>(code)]
                == (std::numeric_limits<std::size_t>::max)())
            return false;
        ++counts[static_cast<std::size_t>(code)];
        return true;
    };
    for (std::size_t i = 0u; i < record.groups.size(); ++i) {
        const DRW_Variant& field = record.groups[i];
        const int code = field.code();
        if (record.spans[i].ignoredComment)
            continue;
        if (code == 102 || (code >= 1000 && code <= 1071))
            return false;
        if (code == 100) {
            if (!isText(field))
                return false;
            const std::string& subclass = *field.content.s;
            if (subclassCount == 0u && subclass == "AcDbEntity")
                scope = Scope::Entity;
            else if (subclassCount == 1u && subclass == "AcDbPointCloud")
                scope = Scope::PointCloud;
            else
                return false;
            ++subclassCount;
            continue;
        }
        if (scope != Scope::PointCloud) {
            bool projected = false;
            switch (code) {
            case 5: case 6: case 8: case 330: case 347: case 348:
            case 360: case 390: case 430:
                projected = isText(field);
                break;
            case 48:
                projected = isReal(field);
                break;
            case 60: case 62: case 67: case 284: case 370: case 420:
            case 440:
                projected = isInt(field);
                break;
            case 160: case 310:
                return false;
            default:
                break;
            }
            if (!projected || !increment(commonCounts, code))
                return false;
            if (code == 5) {
                entityHandleMatched = handleMatches(field, cloud.handle, true);
                if (!entityHandleMatched)
                    return false;
            } else if (code == 6) {
                if (*field.content.s != cloud.lineType)
                    return false;
            } else if (code == 8) {
                if (*field.content.s != cloud.layer)
                    return false;
            } else if (code == 330) {
                entityOwnerMatched =
                    handleMatches(field, cloud.parentHandle, true);
                if (!entityOwnerMatched)
                    return false;
            } else if (code == 347) {
                if (!handleMatches(field, cloud.material, false))
                    return false;
            } else if (code == 348) {
                if (!handleMatches(field, cloud.fullVisualStyleHandle, false))
                    return false;
            } else if (code == 360) {
                if (!handleMatches(field, cloud.xDictHandle, false))
                    return false;
            } else if (code == 390) {
                if (!handleMatches(field,
                        static_cast<std::uint32_t>(cloud.plotStyle), false))
                    return false;
            } else if (code == 430) {
                if (*field.content.s != cloud.colorName)
                    return false;
            } else if (code == 48) {
                if (!sameReal(field.content.d, cloud.ltypeScale))
                    return false;
            } else if (code == 60) {
                if ((field.i_val() != 0 && field.i_val() != 1)
                    || cloud.visible != (field.i_val() == 0))
                    return false;
            } else if (code == 62) {
                if (field.i_val() != cloud.color)
                    return false;
            } else if (code == 67) {
                if (field.i_val() != static_cast<int>(cloud.space))
                    return false;
            } else if (code == 284) {
                if (field.i_val() != static_cast<int>(cloud.shadow))
                    return false;
            } else if (code == 370) {
                if (field.i_val()
                    != DRW_LW_Conv::lineWidth2dxfInt(cloud.lWeight))
                    return false;
            } else if (code == 420) {
                if (field.i_val() != cloud.color24)
                    return false;
            } else if (code == 440) {
                if (field.i_val() != cloud.transparency)
                    return false;
            }
            continue;
        }

        if (!increment(bodyCounts, code))
            return false;
        switch (code) {
        case 70:
            if (!isInt(field) || field.i_val()
                    != static_cast<int>(cloud.classVersion))
                return false;
            ++classVersionCount;
            break;
        case 10: case 20: case 30:
        case 11: case 21: case 31:
        case 12: case 22: case 32:
        case 13: case 23: case 33:
        case 210: case 220: case 230:
        case 211: case 221: case 231:
        case 212: case 222: case 232: {
            if (!isReal(field))
                return false;
            const DRW_Coord* point = nullptr;
            int componentCode = 0;
            if (code >= 210) {
                switch (code % 10) {
                case 0: point = &cloud.ucsXDirection; break;
                case 1: point = &cloud.ucsYDirection; break;
                case 2: point = &cloud.ucsZDirection; break;
                default: return false;
                }
                componentCode = code / 10 - 21;
            } else {
                point = code < 40
                    ? (code == 10 || code == 20 || code == 30
                        ? &cloud.origin
                        : code == 11 || code == 21 || code == 31
                            ? &cloud.extentsMin
                            : code == 12 || code == 22 || code == 32
                                ? &cloud.extentsMax : &cloud.ucsOrigin)
                    : nullptr;
                componentCode = code / 10 - 1;
            }
            if (point == nullptr)
                return false;
            const double expected = componentCode == 0 ? point->x
                : componentCode == 1 ? point->y : point->z;
            if (!sameReal(field.content.d, expected))
                return false;
            break;
        }
        case 1:
            if (!isText(field) || *field.content.s != cloud.savedFilename)
                return false;
            break;
        case 90:
            if (!isInt(field) || field.i_val() != cloud.sourceFileCount)
                return false;
            ++sourceCountCount;
            break;
        case 2:
            if (!isText(field)
                || sourceFileIndex >= cloud.sourceFiles.size()
                || *field.content.s != cloud.sourceFiles[sourceFileIndex])
                return false;
            ++sourceFileIndex;
            break;
        case 92:
            if (!isInt(field) || field.i_val()
                    != static_cast<std::int32_t>(cloud.pointCount))
                return false;
            ++pointCountCount;
            break;
        case 3:
            if (!isText(field) || *field.content.s != cloud.ucsName)
                return false;
            break;
        case 330:
            if (!handleMatches(field, cloud.definitionHandle,
                               allowDefinitionReferences))
                return false;
            ++definitionReferenceCount;
            break;
        case 360:
            if (!handleMatches(field, cloud.reactorHandle,
                               allowDefinitionReferences))
                return false;
            ++reactorReferenceCount;
            break;
        case 71:
            if (!isInt(field) || field.i_val() != cloud.intensityScheme)
                return false;
            break;
        case 40: case 41: case 42: case 43: {
            if (!isReal(field))
                return false;
            const double expected = code == 40
                ? cloud.intensityStyle.minIntensity
                : code == 41 ? cloud.intensityStyle.maxIntensity
                : code == 42 ? cloud.intensityStyle.lowThreshold
                             : cloud.intensityStyle.highThreshold;
            if (!sameReal(field.content.d, expected))
                return false;
            break;
        }
        default:
            return false;
        }
    }
    if (scope != Scope::PointCloud || subclassCount != 2u
        || !entityHandleMatched || !entityOwnerMatched
        || classVersionCount != 1u || sourceCountCount != 1u
        || pointCountCount != 1u
        || (allowDefinitionReferences
            && (definitionReferenceCount != 1u
                || reactorReferenceCount != 1u))
        || sourceFileIndex != cloud.sourceFiles.size())
        return false;
    for (std::size_t code = 0u; code < commonCounts.size(); ++code) {
        if (commonCounts[code] > 1u)
            return false;
    }
    for (std::size_t code = 0u; code < bodyCounts.size(); ++code) {
        if (code != 2u && bodyCounts[code] > 1u)
            return false;
    }
    return true;
}

bool pointCloudExSourceFieldProfileComplete(
        const DRW_DxfPhysicalEntitySource& record,
        const DRW_PointCloudEx& cloud, DRW::Version version,
        bool binary) noexcept {
    if (!pointCloudExPhysicalRecordValid(record, version, binary)
        || version < DRW::AC1027)
        return false;
    enum class Scope : std::uint8_t { Header, Entity, PointCloud };
    Scope scope = Scope::Header;
    std::size_t subclassCount = 0u;
    std::size_t textField = 0u;
    std::size_t stylizationField = 0u;
    std::size_t elevationMinField = 0u;
    std::size_t zeroCropUnknownField = 0u;
    std::size_t cropCount = 0u;
    std::size_t activeCrop = (std::numeric_limits<std::size_t>::max)();
    std::size_t cropBooleanCount = 0u;
    std::size_t cropPlaneComponent = 0u;
    std::size_t cropDirectionComponent = 0u;
    std::size_t cropPointCountFields = 0u;
    std::size_t cropPointCount = 0u;
    std::size_t cropPointComponent = 0u;
    std::size_t cropPointIndex = 0u;
    bool entityHandleMatched = false;
    bool entityOwnerMatched = false;
    bool definitionReferenceMatched = false;
    bool reactorReferenceMatched = false;
    bool lockedFieldSeen = false;
    bool showIntensitySeen = false;
    bool showCroppingSeen = false;
    bool elevationFixedRangeSeen = false;
    bool intensityGradientSeen = false;
    bool elevationGradientSeen = false;
    std::array<std::size_t, 1072u> commonCounts{};
    std::array<std::size_t, 1072u> pointCloudCounts{};
    const auto isType = [](const DRW_Variant& field,
                           DRW_Variant::TYPE type) {
        return field.type() == type;
    };
    const auto isText = [&isType](const DRW_Variant& field) {
        return isType(field, DRW_Variant::STRING)
            && field.content.s != nullptr;
    };
    const auto isInt = [&isType](const DRW_Variant& field) {
        return isType(field, DRW_Variant::INTEGER);
    };
    const auto isReal = [&isType](const DRW_Variant& field) {
        return isType(field, DRW_Variant::DOUBLE)
            && std::isfinite(field.content.d);
    };
    const auto sameReal = [](double left, double right) {
        return std::memcmp(&left, &right, sizeof(left)) == 0;
    };
    const auto isHandle = [](const DRW_Variant& field,
                             std::uint32_t expected) {
        if (field.type() != DRW_Variant::STRING || field.content.s == nullptr
            || field.content.s->empty())
            return false;
        std::uint64_t parsedHandle = 0u;
        const std::string& text = *field.content.s;
        const auto parsed = std::from_chars(
            text.data(), text.data() + text.size(), parsedHandle, 16);
        return parsed.ec == std::errc{}
            && parsed.ptr == text.data() + text.size()
            && parsedHandle <= (std::numeric_limits<std::uint32_t>::max)()
            && parsedHandle == expected;
    };
    const auto increment = [](std::array<std::size_t, 1072u>& counts,
                              int code) {
        if (code < 0 || static_cast<std::size_t>(code) >= counts.size()
            || counts[static_cast<std::size_t>(code)]
                == (std::numeric_limits<std::size_t>::max)())
            return false;
        ++counts[static_cast<std::size_t>(code)];
        return true;
    };
    const auto validCropEnd = [&cloud, &activeCrop, &cropBooleanCount,
                               &cropPlaneComponent, &cropDirectionComponent,
                               &cropPointCountFields, &cropPointCount,
                               &cropPointComponent, &cropPointIndex]() {
        if (activeCrop == (std::numeric_limits<std::size_t>::max)())
            return true;
        const DRW_PointCloudExCropping& crop = cloud.croppings[activeCrop];
        return cropBooleanCount == 2u && cropPlaneComponent == 3u
            && cropDirectionComponent == 6u && cropPointCountFields == 1u
            && cropPointComponent == 0u && cropPointIndex == cropPointCount
            && cropPointCount == crop.points.size();
    };
    for (std::size_t i = 0u; i < record.groups.size(); ++i) {
        const DRW_Variant& field = record.groups[i];
        const int code = field.code();
        if (record.spans[i].ignoredComment)
            continue;
        // The current imported graph route refuses application data and
        // XDATA. Fail here instead of treating recognizable scalar encodings
        // as a complete output field profile.
        if (code == 102 || (code >= 1000 && code <= 1071))
            return false;
        if (code == 100) {
            if (!isText(field))
                return false;
            const std::string& subclass = *field.content.s;
            if (subclassCount == 0u && subclass == "AcDbEntity")
                scope = Scope::Entity;
            else if (subclassCount == 1u
                     && subclass == "AcDbPointCloud")
                scope = Scope::PointCloud;
            else
                return false;
            ++subclassCount;
            continue;
        }
        if (scope != Scope::PointCloud) {
            bool projected = false;
            switch (code) {
            case 5:
            case 6:
            case 8:
            case 330:
            case 347:
            case 348:
            case 360:
            case 390:
            case 430:
                projected = isText(field);
                break;
            case 48:
                projected = isReal(field);
                break;
            case 60:
            case 62:
            case 67:
            case 284:
            case 370:
            case 420:
            case 440:
                projected = isInt(field);
                break;
            case 160:
            case 310:
                // Proxy graphics are not admitted by the current point-cloud
                // graph writer; never let its physical payload be dropped.
                return false;
            default:
                break;
            }
            if (!projected)
                return false;
            if (code == 5) {
                entityHandleMatched = isHandle(field, cloud.handle);
                if (!entityHandleMatched)
                    return false;
            } else if (code == 6) {
                if (*field.content.s != cloud.lineType)
                    return false;
            } else if (code == 8) {
                if (*field.content.s != cloud.layer)
                    return false;
            } else if (code == 330) {
                entityOwnerMatched = isHandle(field, cloud.parentHandle);
                if (!entityOwnerMatched)
                    return false;
            } else if (code == 347) {
                if (!isHandle(field, cloud.material))
                    return false;
            } else if (code == 348) {
                if (!isHandle(field, cloud.fullVisualStyleHandle))
                    return false;
            } else if (code == 360) {
                if (!isHandle(field, cloud.xDictHandle))
                    return false;
            } else if (code == 390) {
                if (!isHandle(field, static_cast<std::uint32_t>(
                                         cloud.plotStyle)))
                    return false;
            } else if (code == 430) {
                if (*field.content.s != cloud.colorName)
                    return false;
            } else if (code == 48) {
                if (!isReal(field)
                    || std::memcmp(&field.content.d, &cloud.ltypeScale,
                                   sizeof(cloud.ltypeScale)) != 0)
                    return false;
            } else if (code == 60) {
                if (!isInt(field) || (field.i_val() != 0
                                      && field.i_val() != 1)
                    || cloud.visible != (field.i_val() == 0))
                    return false;
            } else if (code == 62) {
                if (!isInt(field) || field.i_val() != cloud.color)
                    return false;
            } else if (code == 67) {
                if (!isInt(field)
                    || field.i_val() != static_cast<int>(cloud.space))
                    return false;
            } else if (code == 284) {
                if (!isInt(field)
                    || field.i_val() != static_cast<int>(cloud.shadow))
                    return false;
            } else if (code == 370) {
                if (!isInt(field)
                    || field.i_val()
                        != DRW_LW_Conv::lineWidth2dxfInt(cloud.lWeight))
                    return false;
            } else if (code == 420) {
                if (!isInt(field) || field.i_val() != cloud.color24)
                    return false;
            } else if (code == 440) {
                if (!isInt(field) || field.i_val() != cloud.transparency)
                    return false;
            }
            if (!increment(commonCounts, code))
                return false;
            continue;
        }

        switch (code) {
        case 1: {
            if (!isText(field) || textField >= 4u)
                return false;
            const std::string* expected = textField == 0u ? &cloud.name
                : textField == 1u ? &cloud.intensityColorScheme
                : textField == 2u ? &cloud.currentColorScheme
                : &cloud.classificationColorScheme;
            if (*field.content.s != *expected)
                return false;
            ++textField;
            break;
        }
        case 330:
            definitionReferenceMatched =
                isHandle(field, cloud.definitionHandle);
            if (!definitionReferenceMatched)
                return false;
            break;
        case 360:
            reactorReferenceMatched = isHandle(field, cloud.reactorHandle);
            if (!reactorReferenceMatched)
                return false;
            break;
        case 10: case 11: case 12:
        case 20: case 21: case 22:
        case 30: case 31: case 32: {
            if (!isReal(field))
                return false;
            const double expected = code == 10 ? cloud.extentsMin.x
                : code == 11 ? cloud.extentsMax.x
                : code == 12 ? cloud.ucsOrigin.x
                : code == 20 ? cloud.extentsMin.y
                : code == 21 ? cloud.extentsMax.y
                : code == 22 ? cloud.ucsOrigin.y
                : code == 30 ? cloud.extentsMin.z
                : code == 31 ? cloud.extentsMax.z : cloud.ucsOrigin.z;
            if (!sameReal(field.content.d, expected))
                return false;
            break;
        }
        case 13: case 23: case 33: {
            if (!isReal(field))
                return false;
            const std::size_t component = code == 13 ? 0u
                : code == 23 ? 1u : 2u;
            double expected = 0.0;
            if (activeCrop == (std::numeric_limits<std::size_t>::max)()) {
                expected = component == 0u ? cloud.ucsOrigin.x
                    : component == 1u ? cloud.ucsOrigin.y
                    : cloud.ucsOrigin.z;
            } else if (cropPlaneComponent < 3u) {
                if (component != cropPlaneComponent)
                    return false;
                const DRW_Coord& plane =
                    cloud.croppings[activeCrop].cropPlane;
                expected = component == 0u ? plane.x
                    : component == 1u ? plane.y : plane.z;
                ++cropPlaneComponent;
            } else {
                if (cropPointCountFields != 1u
                    || cropPointComponent != component
                    || cropPointIndex
                        >= cloud.croppings[activeCrop].points.size())
                    return false;
                const DRW_Coord& point =
                    cloud.croppings[activeCrop].points[cropPointIndex];
                expected = component == 0u ? point.x
                    : component == 1u ? point.y : point.z;
                ++cropPointComponent;
                if (cropPointComponent == 3u) {
                    cropPointComponent = 0u;
                    ++cropPointIndex;
                }
            }
            if (!sameReal(field.content.d, expected))
                return false;
            break;
        }
        case 40:
            if (!isReal(field) || elevationMinField >= 2u
                || !sameReal(field.content.d,
                    elevationMinField++ == 0u
                        ? cloud.elevationMin : cloud.elevationMax))
                return false;
            break;
        case 41:
            if (!isReal(field) || !sameReal(field.content.d,
                                             cloud.elevationMax))
                return false;
            break;
        case 210: case 220: case 230:
        case 211: case 221: case 231:
        case 212: case 222: case 232: {
            if (!isReal(field))
                return false;
            const DRW_Coord& direction = code % 10 == 0
                ? cloud.ucsXDirection : code % 10 == 1
                ? cloud.ucsYDirection : cloud.ucsZDirection;
            const int component = (code / 10) % 10 - 1;
            const double expected = component == 0 ? direction.x
                : component == 1 ? direction.y : direction.z;
            if (!sameReal(field.content.d, expected))
                return false;
            break;
        }
        case 213: case 223: case 233: {
            if (!isReal(field)
                || activeCrop == (std::numeric_limits<std::size_t>::max)()
                || cropDirectionComponent >= 6u)
                return false;
            const std::size_t component = cropDirectionComponent % 3u;
            if (component != (code == 213 ? 0u : code == 223 ? 1u : 2u))
                return false;
            const DRW_PointCloudExCropping& cropping =
                cloud.croppings[activeCrop];
            const DRW_Coord& direction = cropDirectionComponent < 3u
                ? cropping.cropXDirection : cropping.cropYDirection;
            const double expected = component == 0u ? direction.x
                : component == 1u ? direction.y : direction.z;
            if (!sameReal(field.content.d, expected))
                return false;
            ++cropDirectionComponent;
            break;
        }
        case 70:
            if (!isInt(field) || field.i_val() < 0
                || field.i_val()
                    > std::numeric_limits<std::uint16_t>::max()
                || static_cast<std::uint32_t>(field.i_val())
                    != cloud.classVersion)
                return false;
            break;
        case 71:
            if (!isInt(field) || stylizationField >= 2u
                || field.i_val() != (stylizationField++ == 0u
                    ? cloud.stylizationType
                    : cloud.intensityOutOfRangeBehavior))
                return false;
            break;
        case 72:
            if (!isInt(field)
                || field.i_val() != cloud.elevationOutOfRangeBehavior)
                return false;
            break;
        case 90:
            if (!isInt(field)
                || cloud.intensityMin != static_cast<double>(field.i_val()))
                return false;
            break;
        case 91:
            if (!isInt(field)
                || cloud.intensityMax != static_cast<double>(field.i_val()))
                return false;
            break;
        case 92:
            if (!isInt(field) || field.i_val() != cloud.croppingCount)
                return false;
            break;
        case 93:
            if (!isInt(field))
                return false;
            if (activeCrop == (std::numeric_limits<std::size_t>::max)()) {
                if (cloud.croppingCount != 0 || zeroCropUnknownField >= 2u
                    || field.i_val() != (zeroCropUnknownField++ == 0u
                        ? cloud.unknownInt0 : cloud.unknownInt1))
                    return false;
            } else {
                const DRW_PointCloudExCropping& cropping =
                    cloud.croppings[activeCrop];
                if (cropPlaneComponent != 3u
                    || cropDirectionComponent != 6u
                    || cropPointCountFields != 0u || field.i_val() < 0
                    || field.i_val() != cropping.pointCount
                    || cropping.points.size()
                        != static_cast<std::size_t>(field.i_val()))
                    return false;
                cropPointCountFields = 1u;
                cropPointCount = static_cast<std::size_t>(field.i_val());
            }
            break;
        case 280:
            if (!isInt(field) || field.i_val() < 0
                || field.i_val()
                    > std::numeric_limits<std::uint16_t>::max()
                || !validCropEnd() || cropCount >= cloud.croppings.size()
                || field.i_val() != cloud.croppings[cropCount].type)
                return false;
            activeCrop = cropCount++;
            cropBooleanCount = 0u;
            cropPlaneComponent = 0u;
            cropDirectionComponent = 0u;
            cropPointCountFields = 0u;
            cropPointCount = 0u;
            cropPointComponent = 0u;
            cropPointIndex = 0u;
            break;
        case 290:
            if (!isInt(field) || (field.i_val() != 0 && field.i_val() != 1))
                return false;
            if (activeCrop == (std::numeric_limits<std::size_t>::max)()) {
                if (lockedFieldSeen
                    || cloud.isLocked != (field.i_val() != 0))
                    return false;
                lockedFieldSeen = true;
            } else {
                if (cropBooleanCount >= 2u
                    || (cropBooleanCount == 0u
                        ? cloud.croppings[activeCrop].isInside
                        : cloud.croppings[activeCrop].isInverted)
                            != (field.i_val() != 0))
                    return false;
                ++cropBooleanCount;
            }
            break;
        case 291:
            if (!isInt(field) || showIntensitySeen
                || (field.i_val() != 0 && field.i_val() != 1)
                || cloud.showIntensity != (field.i_val() != 0))
                return false;
            showIntensitySeen = true;
            break;
        case 292:
            if (!isInt(field) || elevationFixedRangeSeen
                || (field.i_val() != 0 && field.i_val() != 1)
                || cloud.elevationApplyToFixedRange != (field.i_val() != 0))
                return false;
            elevationFixedRangeSeen = true;
            break;
        case 293:
            if (!isInt(field) || intensityGradientSeen
                || (field.i_val() != 0 && field.i_val() != 1)
                || cloud.intensityAsGradient != (field.i_val() != 0))
                return false;
            intensityGradientSeen = true;
            break;
        case 294:
            if (!isInt(field) || elevationGradientSeen
                || (field.i_val() != 0 && field.i_val() != 1)
                || cloud.elevationAsGradient != (field.i_val() != 0))
                return false;
            elevationGradientSeen = true;
            break;
        case 295:
            if (!isInt(field) || showCroppingSeen
                || (field.i_val() != 0 && field.i_val() != 1)
                || cloud.showCropping != (field.i_val() != 0))
                return false;
            showCroppingSeen = true;
            break;
        default:
            return false;
        }
        if (!increment(pointCloudCounts, code))
            return false;
    }
    static constexpr std::array<int, 18u> singletonBodyCodes{{
        10, 11, 12, 20, 21, 22, 30, 31, 32,
        210, 220, 230, 211, 221, 231, 212, 222, 232
    }};
    for (const int code : singletonBodyCodes) {
        if (pointCloudCounts[static_cast<std::size_t>(code)] > 1u)
            return false;
    }
    if (!validCropEnd() || subclassCount != 2u || cloud.croppingCount < 0
        || cloud.croppings.size()
            != static_cast<std::size_t>(cloud.croppingCount)
        || commonCounts[5u] != 1u || commonCounts[330u] != 1u
        || !entityHandleMatched || !entityOwnerMatched
        || pointCloudCounts[70u] != 1u || pointCloudCounts[92u] != 1u
        || pointCloudCounts[330u] != 1u || !definitionReferenceMatched
        || pointCloudCounts[360u] != 1u || !reactorReferenceMatched
        || pointCloudCounts[280u]
            != static_cast<std::size_t>(cloud.croppingCount)
        || cropCount != cloud.croppings.size()
        || pointCloudCounts[1u] > 4u || pointCloudCounts[71u] > 2u
        || pointCloudCounts[72u] > 1u || pointCloudCounts[90u] > 1u
        || pointCloudCounts[91u] > 1u || pointCloudCounts[40u] > 2u
        || pointCloudCounts[41u] > 1u || pointCloudCounts[291u] > 1u
        || pointCloudCounts[292u] > 1u || pointCloudCounts[293u] > 1u
        || pointCloudCounts[294u] > 1u || pointCloudCounts[295u] > 1u
        || pointCloudCounts[330u] > 1u || pointCloudCounts[360u] > 1u
        || pointCloudCounts[93u]
            != (cloud.croppingCount == 0
                    ? 2u
                    : static_cast<std::size_t>(cloud.croppingCount)))
    {
        return false;
    }
    const std::size_t expectedCroppingBooleans =
        static_cast<std::size_t>(cloud.croppingCount) * 2u;
    return pointCloudCounts[290u] >= expectedCroppingBooleans
        && pointCloudCounts[290u]
            == expectedCroppingBooleans
                + static_cast<std::size_t>(lockedFieldSeen)
        && zeroCropUnknownField
            == (cloud.croppingCount == 0 ? 2u : 0u);
}

bool pointCloudExDispatchMatchesRecord(
        const DRW_DxfPhysicalEntitySource& record,
        const DRW_DxfPhysicalRecordSpan& begin,
        const DRW_DxfPhysicalRecordSpan& end) noexcept {
    return record.marker.ordinal == begin.ordinal
        && record.marker.beginOffset == begin.beginOffset
        && record.marker.endOffset == begin.endOffset
        && record.marker.ignoredComment == begin.ignoredComment
        && record.endOrdinal == end.ordinal
        && record.endOffset == end.beginOffset;
}

bool estimateNavisworksDefinitionBytes(
        const DRW_NavisworksModelDef& value, std::size_t& estimate,
        std::size_t& itemCount) noexcept {
    estimate = sizeof(DRW_NavisworksModelDef);
    itemCount = value.reactorHandles.size();
    if (value.tType != DRW::NAVISWORKSMODELDEF
        || value.m_flags < 0
        || value.m_flags > DRW_NavisworksModelDef::kMaxFlags
        || value.m_path.size() > DRW_NavisworksModelDef::kMaxPathLength
        || itemCount > kMaxAdapterPointCloudObjectItems
        || !addTableEntryRetainedBytes(value, estimate))
        return false;
    const auto addItems = [&itemCount](std::size_t count) noexcept {
        if (itemCount > kMaxAdapterPointCloudObjectItems
            || count > kMaxAdapterPointCloudObjectItems - itemCount)
            return false;
        itemCount += count;
        return true;
    };
    if (!addItems(value.extData.size()) || !addItems(value.appData.size()))
        return false;
    for (const auto& group : value.appData) {
        if (!addItems(group.size()))
            return false;
    }
    if (!addStringPayloadBytes(value.m_path, estimate))
        return false;
    return estimate <= kMaxAdapterPointCloudObjectRetainedBytes;
}

bool estimatePointCloudColorMapBytes(
        const DRW_PointCloudColorMap& value, std::size_t& estimate,
        std::size_t& itemCount) noexcept {
    estimate = sizeof(DRW_PointCloudColorMap);
    itemCount = value.reactorHandles.size();
    const auto addItems = [&itemCount](std::size_t count) noexcept {
        if (itemCount > kMaxAdapterPointCloudObjectItems
            || count > kMaxAdapterPointCloudObjectItems - itemCount)
            return false;
        itemCount += count;
        return true;
    };
    const auto addRamps = [&estimate, &addItems](
            const std::vector<DRW_PointCloudColorMapRamp>& ramps) noexcept {
        if (!addVectorPayloadBytes(ramps, estimate)
            || !addItems(ramps.size()))
            return false;
        for (const DRW_PointCloudColorMapRamp& ramp : ramps) {
            if (ramp.m_classVersion < 0
                || ramp.m_classVersion
                    > DRW_PointCloudColorMap::kMaxClassVersion
                || ramp.m_rampCount
                    > DRW_PointCloudColorMap::kMaxColorsPerRamp
                || ramp.m_colorSchemes.size() > ramp.m_rampCount
                || !addVectorPayloadBytes(ramp.m_colorSchemes, estimate)
                || !addItems(ramp.m_colorSchemes.size()))
                return false;
            for (const UTF8STRING& scheme : ramp.m_colorSchemes) {
                if (scheme.size()
                        > DRW_PointCloudColorMap::kMaxColorSchemeLength
                    || !addStringPayloadBytes(scheme, estimate))
                    return false;
            }
        }
        return true;
    };
    if (value.tType != DRW::POINTCLOUDCOLORMAP
        || value.m_classVersion < 0
        || value.m_classVersion > DRW_PointCloudColorMap::kMaxClassVersion
        || value.m_colorRampCount > DRW_PointCloudColorMap::kMaxRamps
        || value.m_classificationColorRampCount
               > DRW_PointCloudColorMap::kMaxRamps
        || value.m_colorRampCount != value.m_colorRamps.size()
        || value.m_classificationColorRampCount
               != value.m_classificationColorRamps.size()
        || itemCount > kMaxAdapterPointCloudObjectItems
        || !addTableEntryRetainedBytes(value, estimate)
        || !addStringPayloadBytes(value.m_defaultIntensityColorScheme,
                                  estimate)
        || !addStringPayloadBytes(value.m_defaultElevationColorScheme,
                                  estimate)
        || !addStringPayloadBytes(
            value.m_defaultClassificationColorScheme, estimate)
        || value.m_defaultIntensityColorScheme.size()
               > DRW_PointCloudColorMap::kMaxColorSchemeLength
        || value.m_defaultElevationColorScheme.size()
               > DRW_PointCloudColorMap::kMaxColorSchemeLength
        || value.m_defaultClassificationColorScheme.size()
               > DRW_PointCloudColorMap::kMaxColorSchemeLength
        || !addRamps(value.m_colorRamps)
        || !addRamps(value.m_classificationColorRamps))
        return false;
    if (!addItems(value.extData.size()) || !addItems(value.appData.size()))
        return false;
    for (const auto& group : value.appData) {
        if (!addItems(group.size()))
            return false;
    }
    return estimate <= kMaxAdapterPointCloudObjectRetainedBytes;
}

template <typename T, typename Estimate>
void retainPointCloudObjectTyped(
        dx_data* data, std::list<T>& records, const T& value,
        Estimate estimate) noexcept {
    if (data == nullptr || data->pointCloudObjectCaptureFailed)
        return;
    if (data->pointCloudObjectRetainedRecords
        >= kMaxAdapterPointCloudObjectRecords) {
        data->pointCloudObjectCaptureFailed = true;
        return;
    }

    std::size_t estimatedBytes = 0u;
    std::size_t itemCount = 0u;
    if (!estimate(value, estimatedBytes, itemCount)
        || data->pointCloudObjectRetainedItems
            > kMaxAdapterPointCloudObjectItems
        || itemCount > kMaxAdapterPointCloudObjectItems
                            - data->pointCloudObjectRetainedItems
        || data->pointCloudObjectRetainedBytes
            > kMaxAdapterPointCloudObjectRetainedBytes
        || estimatedBytes > kMaxAdapterPointCloudObjectRetainedBytes
                                - data->pointCloudObjectRetainedBytes) {
        data->pointCloudObjectCaptureFailed = true;
        return;
    }

    try {
        records.push_back(value);
        ++data->pointCloudObjectRetainedRecords;
        data->pointCloudObjectRetainedItems += itemCount;
        data->pointCloudObjectRetainedBytes += estimatedBytes;
    } catch (...) {
        data->pointCloudObjectCaptureFailed = true;
    }
}

