void dx_iface::rejectStandardDwgObjectCapture() noexcept {
    if (cData != nullptr) {
        cData->m_standardDwgObjectCaptureFailed = true;
        cData->dwgReadOutcome.standardObjectCaptureFailed = true;
    }
}

void dx_iface::retainStandardDwgAppIdSource(const DRW_AppId& data) {
    if (cData == nullptr || cData->m_standardDwgObjectCaptureFailed
        || cData->sourceFormat != dx_source_format::DWG
        || cData->importGeneration == 0u
        || cData->importGeneration <= cData->m_standardDwgNamesClosedThrough)
        return;
    try {
        std::size_t bytes = 0u, items = 0u;
        const dx_data::StandardDwgFrameKey key{cData->importGeneration, data.handle};
        const auto names = cData->m_standardDwgAppIdSources.size()
            + cData->m_standardDwgLayerSources.size();
        if (data.handle == 0u || data.handle == DRW::NoHandle
            || cData->m_standardDwgAppIdSources.count(key) != 0u
            || cData->m_standardDwgObjectFrames.count(key) != 0u
            || cData->m_standardDwgLayerSources.count(key) != 0u
            || names >= StandardDwgObjectCaptureMaxRecords
            || cData->m_standardDwgObjectFrames.size()
                >= StandardDwgObjectCaptureMaxRecords
                    - names
            || !estimateAppIdTypedBytes(data, bytes, items)
            || !addAssociativeRetainedBytes(
                sizeof(dx_data::StandardDwgFrameKey) + 6u * sizeof(void*), bytes)
            || !standardDwgCaptureFits(cData->m_standardDwgObjectRetainedBytes, bytes)) {
            rejectStandardDwgObjectCapture();
            return;
        }
        auto snapshot = std::make_shared<const DRW_AppId>(data);
        cData->m_standardDwgAppIdSources.emplace(key, std::move(snapshot));
        cData->m_standardDwgObjectRetainedBytes += bytes;
    } catch (...) {
        rejectStandardDwgObjectCapture();
    }
}

void dx_iface::retainStandardDwgLayerSource(const DRW_Layer& data) {
    if (cData == nullptr || cData->m_standardDwgObjectCaptureFailed
        || cData->sourceFormat != dx_source_format::DWG
        || cData->importGeneration == 0u
        || cData->importGeneration <= cData->m_standardDwgNamesClosedThrough)
        return;
    try {
        std::size_t bytes = 0u, items = 0u;
        const dx_data::StandardDwgFrameKey key{cData->importGeneration, data.handle};
        const auto names = cData->m_standardDwgAppIdSources.size()
            + cData->m_standardDwgLayerSources.size();
        if (data.handle == 0u || data.handle == DRW::NoHandle
            || cData->m_standardDwgAppIdSources.count(key) != 0u
            || cData->m_standardDwgLayerSources.count(key) != 0u
            || cData->m_standardDwgObjectFrames.count(key) != 0u
            || names >= StandardDwgObjectCaptureMaxRecords
            || cData->m_standardDwgObjectFrames.size() >= StandardDwgObjectCaptureMaxRecords - names
            || !estimateLayerTypedBytes(data, bytes, items)
            || !addAssociativeRetainedBytes(
                sizeof(dx_data::StandardDwgFrameKey) + 6u * sizeof(void*), bytes)
            || !standardDwgCaptureFits(cData->m_standardDwgObjectRetainedBytes, bytes)) {
            rejectStandardDwgObjectCapture();
            return;
        }
        auto snapshot = std::make_shared<const DRW_Layer>(data);
        cData->m_standardDwgLayerSources.emplace(key, std::move(snapshot));
        cData->m_standardDwgObjectRetainedBytes += bytes;
    } catch (...) {
        rejectStandardDwgObjectCapture();
    }
}

void dx_iface::beginRasterDwgNamesRead(dx_data& data) noexcept {
    m_rasterDwgNameRead.reset();
    const auto existing = data.m_rasterDwgNameImports.find(data.m_classEvidenceGeneration);
    if (existing != data.m_rasterDwgNameImports.end()) { existing->second->valid = false; return; }
    if (!m_classEvidenceReadAttempt || data.m_classEvidenceFailure.state == dx_class_evidence::State::ContextMismatch)
        return;
    const auto bytes = sizeof(dx_data::RasterDwgNameImport) + 8u * sizeof(void*);
    if (data.m_rasterDwgNameImports.size() >= data.m_rasterDwgNameImportLimit
        || data.m_rasterDwgNameBytes > data.m_rasterDwgNameByteLimit
        || bytes > data.m_rasterDwgNameByteLimit - data.m_rasterDwgNameBytes) return;
    try {
        auto value = std::make_shared<dx_data::RasterDwgNameImport>();
        value->attempt = m_classEvidenceReadAttempt; value->generation = data.m_classEvidenceGeneration;
        value->retainedBytes = bytes;
        data.m_rasterDwgNameImports.emplace(value->generation, value);
        data.m_rasterDwgNameBytes += bytes; m_rasterDwgNameRead = std::move(value);
    } catch (...) { m_rasterDwgNameRead.reset(); }
}

void dx_iface::retainRasterDwgName(std::uint32_t handle, const UTF8STRING& name,
        const std::shared_ptr<const DRW_DwgTableNameSource>& source, bool layer) noexcept {
    if (!m_rasterDwgNameRead || !m_classEvidenceReadData) return; // Late/authored callbacks cannot refresh a receipt.
    auto& read = *m_rasterDwgNameRead; auto& data = *m_classEvidenceReadData;
    if (!read.valid || read.closed) return;
    if (cData != &data || data.m_classEvidenceOwner != this || data.m_classEvidenceAttempt != read.attempt
        || data.importGeneration != read.generation || data.sourceFormat != dx_source_format::DWG) {
        read.valid = false; rejectDwgClassEvidence(data, dx_class_evidence::State::ContextMismatch);
        data.m_rasterDwgSourceFailed = true;
        if (cData) cData->m_rasterDwgSourceFailed = true;
        return;
    }
    auto& rows = layer ? read.layers : read.apps;
    auto& other = layer ? read.apps : read.layers;
    auto& ordinal = layer ? read.layerEvents : read.appEvents;
    if (ordinal >= kMaxAdapterBasicTableRecords || !handle || handle == DRW::NoHandle) { read.valid = false; return; }
    const auto eventOrdinal = ordinal++;
    const auto duplicate = rows.find(handle);
    if (duplicate != rows.end()) { duplicate->second.duplicate = true; return; }
    const auto crossRole = other.find(handle);
    if (crossRole != other.end()) crossRole->second.duplicate = true;
    const auto base = sizeof(dx_data::RasterDwgNameEvent) + sizeof(handle) + 6u * sizeof(void*);
    std::size_t bytes = base;
    const auto add = [&bytes](std::size_t value) {
        if (value > 64u * 1024u * 1024u || bytes > 64u * 1024u * 1024u - value) return false;
        bytes += value; return true;
    };
    if (!add(name.size()) || (source && !add(source->retainedBytes()))
        || data.m_rasterDwgNameBytes > data.m_rasterDwgNameByteLimit
        || bytes > data.m_rasterDwgNameByteLimit - data.m_rasterDwgNameBytes) { read.valid = false; return; }
    try {
        dx_data::RasterDwgNameEvent event;
        event.ordinal = eventOrdinal; event.handle = handle; event.name = name; event.source = source;
        event.duplicate = crossRole != other.end();
        if (event.name.capacity() > event.name.size()) {
            const auto extra = event.name.capacity() - event.name.size();
            if (!add(extra) || bytes > data.m_rasterDwgNameByteLimit - data.m_rasterDwgNameBytes) { read.valid = false; return; }
        }
        rows.emplace(handle, std::move(event));
        read.retainedBytes += bytes; data.m_rasterDwgNameBytes += bytes;
    } catch (...) { read.valid = false; }
}

void dx_iface::finishRasterDwgNamesRead(bool successfulRead, DRW::Version version, std::uint16_t page,
                                      bool present, bool recognized) noexcept {
    if (!m_rasterDwgNameRead || !m_classEvidenceReadData) return;
    auto& read = *m_rasterDwgNameRead; auto& data = *m_classEvidenceReadData;
    read.closed = true; read.version = version; read.codePage = page;
    read.codePagePresent = present; read.codePageRecognized = recognized;
    const bool context = cData == &data
        && data.m_classEvidenceOwner == this && data.m_classEvidenceAttempt == read.attempt
        && data.importGeneration == read.generation && data.sourceFormat == dx_source_format::DWG;
    if (!context) {
        rejectDwgClassEvidence(data, dx_class_evidence::State::ContextMismatch);
        data.m_rasterDwgSourceFailed = true;
        if (cData) cData->m_rasterDwgSourceFailed = true;
    }
    read.valid = read.valid && successfulRead && version != DRW::UNKNOWNV && context;
    if (!read.valid) {
        data.m_rasterDwgNameBytes -= read.retainedBytes;
        data.m_rasterDwgNameImports.erase(read.generation);
    }
    m_rasterDwgNameRead.reset();
}

std::shared_ptr<const dx_data::RasterDwgNameImport> dx_iface::rasterDwgNameImport(
        const dx_data::RasterDwgObjectFrame& frame) const noexcept {
    if (!cData || !frame.classReadAttempt) return {};
    const auto found = cData->m_rasterDwgNameImports.find(frame.generation);
    if (found == cData->m_rasterDwgNameImports.end()) return {};
    const auto& read = found->second;
    return read && read->closed && read->valid && read->attempt == frame.classReadAttempt ? read : nullptr;
}

std::uint64_t dx_iface::rasterClassReadAttempt() noexcept {
    if (m_classEvidenceReadData == nullptr) return 0u;
    auto& data = *m_classEvidenceReadData;
    if (cData != &data || data.m_classEvidenceOwner != this || data.m_classEvidenceAttempt != m_classEvidenceReadAttempt
        || data.importGeneration != data.m_classEvidenceGeneration || data.sourceFormat != dx_source_format::DWG) {
        rejectDwgClassEvidence(data, dx_class_evidence::State::ContextMismatch);
        data.m_rasterDwgSourceFailed = true;
        if (cData != nullptr) cData->m_rasterDwgSourceFailed = true;
        return 0u;
    }
    return m_classEvidenceReadAttempt;
}

dx_class_evidence::RasterBinding dx_iface::rasterClassBinding(const dx_data::RasterDwgObjectFrame& frame) const noexcept {
    using State = dx_class_evidence::RasterState;
    dx_class_evidence::RasterBinding result;
    result.attempt = frame.classReadAttempt;
    const auto& raw = frame.raw; const auto& publication = frame.publication;
    const bool definition = isRasterDwgDefinition(raw);
    if (!frame.publicationSeen || frame.classReadAttempt != frame.classPublicationAttempt
        || publication.m_version != raw.m_version || publication.m_encodedType != raw.m_objectType
        || publication.m_resolvedType != (definition ? dwgObjType::IMAGEDEF : raw.m_objectType)
        || publication.m_isEntity || raw.m_isEntity || publication.m_isCustomClass != raw.m_isCustomClass) {
        result.state = State::Contradiction; return result;
    }
    if (!raw.m_isCustomClass) {
        result.state = definition && raw.m_objectType == dwgObjType::IMAGEDEF && !raw.m_hasClassDefinition
            && raw.m_recordName.empty() && raw.m_className.empty() && raw.m_classAppName.empty()
            && publication.m_recordName.empty() && publication.m_className.empty() && !publication.m_classStreamOrdinal
                ? State::FixedType : State::Contradiction;
        return result;
    }
    if (frame.classReadAttempt == 0u) { result.state = State::NoReadContext; return result; }
    if (cData == nullptr) { result.state = State::TableUnavailable; return result; }
    const auto found = cData->m_classEvidenceImports.find(frame.generation);
    if (found == cData->m_classEvidenceImports.end()) { result.state = State::TableUnavailable; return result; }
    const auto& table = found->second;
    if (!table.closed || table.result.state != dx_class_evidence::State::Joined || !table.rows
        || table.result.attempt != frame.classReadAttempt) { result.state = State::TableUnavailable; return result; }
    const auto page = frame.sourceProfileBound ? frame.sourceCodePageId : cData->dwgReadOutcome.sourceCodePageId;
    const auto present = frame.sourceProfileBound ? frame.sourceCodePageFieldPresent : cData->dwgReadOutcome.sourceCodePageFieldPresent;
    const auto recognized = frame.sourceProfileBound ? frame.sourceCodePageRecognized : cData->dwgReadOutcome.sourceCodePageRecognized;
    if (table.result.version != raw.m_version || table.codePage != page || table.codePagePresent != present
        || table.codePageRecognized != recognized) { result.state = State::Contradiction; return result; }
    result.state = dx_class_evidence::matchRasterRow(*table.rows, raw, publication, definition);
    result.rows = table.rows; result.profileIssues = table.result.profileIssues;
    if (publication.m_classStreamOrdinal) result.ordinal = *publication.m_classStreamOrdinal;
    if (raw.m_objectType >= 500 && raw.m_objectType <= 65535) result.number = static_cast<std::uint16_t>(raw.m_objectType);
    return result;
}

void dx_iface::retainRasterDwgSource(const DRW_UnsupportedObject &data) noexcept {
    if (cData == nullptr || cData->m_rasterDwgSourceFailed)
        return;
    const bool definition = isRasterDwgDefinition(data);
    const bool fixedDefinition = data.m_objectType == dwgObjType::IMAGEDEF
        && !data.m_isCustomClass && !data.m_hasClassDefinition
                                           && data.m_recordName.empty() && data.m_className.empty()
                                           && data.m_classAppName.empty();
    const bool identity = definition ? fixedDefinition || (data.m_isCustomClass && data.m_hasClassDefinition
        && data.m_objectType >= 500 && data.m_recordName == "IMAGEDEF" && data.m_className == "AcDbRasterImageDef")
                                     : data.m_isCustomClass && data.m_hasClassDefinition
                                           && data.m_objectType >= 500
                                           && data.m_recordName == "IMAGEDEF_REACTOR"
                                           && data.m_className == "AcDbRasterImageDefReactor";
    const bool legacyUnknown = data.m_version <= DRW::AC1018
                               && data.m_commonLinkEvidence == DRW_DwgCommonLinkEvidence::Unknown
                               && !data.m_commonHandleDataValidated;
    const dx_data::StandardDwgFrameKey key{cData->importGeneration, data.m_handle};
    std::size_t bytes = 0u;
    if (!identity || data.m_isEntity || !cData->dwgReadOutcome.attempted
        || cData->sourceFormat != dx_source_format::DWG || key.first == 0u
        || key.first <= cData->m_rasterDwgClosedThrough || key.second == 0u
        || key.second == DRW::NoHandle || data.m_version < DRW::AC1012
        || data.m_version > DRW::AC1032 || data.m_rawBytes.empty()
        || data.m_rawBytes.size() != data.m_objectSize
        || data.m_bodyBitSize > static_cast<std::uint64_t>(data.m_objectSize) * 8u
        || data.m_objectOffset > (std::numeric_limits<std::uint32_t>::max)()
        || (!legacyUnknown
            && (!data.m_commonHandleDataValidated
                || !drwDwgCommonLinkEvidenceValidated(data.m_commonLinkEvidence)))
        || data.m_numReactors < 0
        || data.m_reactorHandles.size() != static_cast<std::size_t>(data.m_numReactors)
        || data.m_xDictFlag > 1 || cData->m_rasterDwgSources.count(key) != 0u
        || cData->m_rasterDwgSources.size() >= ImageDefinitionCaptureMaxRecords
        || !estimateAcDsHistoryDwgFrameBytes(data, bytes)
        || !addAssociativeRetainedBytes(sizeof(dx_data::RasterDwgObjectFrame)
                                            + sizeof(dx_data::StandardDwgFrameKey)
                                            + 4u * sizeof(void *),
                                        bytes)
        || cData->m_rasterDwgSourceBytes > ImageDefinitionCaptureMaxRetainedBytes
        || bytes > ImageDefinitionCaptureMaxRetainedBytes - cData->m_rasterDwgSourceBytes) {
        DRW_DBG("Raster DWG raw-source capture rejected handle=");
        DRW_DBGH(data.m_handle);
        DRW_DBG(" type=");
        DRW_DBG(data.m_objectType);
        DRW_DBG(" class=");
        DRW_DBG(data.m_className);
        DRW_DBG(" record=");
        DRW_DBG(data.m_recordName);
        DRW_DBG(" custom=");
        DRW_DBG(data.m_isCustomClass);
        DRW_DBG(" rawBytes/objectSize=");
        DRW_DBG(data.m_rawBytes.size());
        DRW_DBG("/");
        DRW_DBG(data.m_objectSize);
        DRW_DBG(" commonEvidence=");
        DRW_DBG(static_cast<unsigned>(data.m_commonLinkEvidence));
        DRW_DBG(" commonValidated=");
        DRW_DBG(data.m_commonHandleDataValidated);
        DRW_DBG(" reactors=");
        DRW_DBG(data.m_numReactors);
        DRW_DBG("/");
        DRW_DBG(data.m_reactorHandles.size());
        DRW_DBG("\n");
        cData->m_rasterDwgSourceFailed = true;
        return;
    }
    try {
        dx_data::RasterDwgObjectFrame frame;
        frame.raw = data;
        frame.generation = key.first;
        frame.classReadAttempt = rasterClassReadAttempt();
        if (cData->m_rasterDwgSourceFailed) return;
        const auto inserted =
            cData->m_rasterDwgSources.emplace(key, std::move(frame));
        if (!inserted.second) {
            cData->m_rasterDwgSourceFailed = true;
            return;
        }
        cData->m_rasterDwgSourceBytes += bytes;
        if (!recordOpaqueDwgSourceFrameIdentity(data)) {
            cData->m_rasterDwgSources.erase(key);
            cData->m_rasterDwgSourceBytes -= bytes;
            cData->m_rasterDwgSourceFailed = true;
        }
    } catch (...) {
        cData->m_rasterDwgSourceFailed = true;
    }
}

void dx_iface::retainRasterDwgPublication(const DRW_DwgFramePublication &data) noexcept {
    if (cData == nullptr || cData->m_rasterDwgSourceFailed)
        return;
    const auto reject = [this]() { cData->m_rasterDwgSourceFailed = true; };
    const auto found = cData->m_rasterDwgSources.find({cData->importGeneration, data.m_handle});
    if (found == cData->m_rasterDwgSources.end()) {
        reject();
        return;
    }
    auto &frame = found->second;
    const auto &raw = frame.raw;
    const bool legacyUnknown = raw.m_version <= DRW::AC1018
                               && raw.m_commonLinkEvidence == DRW_DwgCommonLinkEvidence::Unknown;
    const dx_data::StandardDwgOrdinalKey ordinal{frame.generation, data.m_sourceMapOrdinal};
    const dx_data::StandardDwgLocationKey location{frame.generation,
                                                   {data.m_sourceOffsetSpace, data.m_sourceOffset}};
    std::size_t bytes = 0u;
    const auto classAttempt = rasterClassReadAttempt();
    if (cData->m_rasterDwgSourceFailed || frame.publicationSeen || frame.generation <= cData->m_rasterDwgClosedThrough
        || frame.classReadAttempt != classAttempt
        || data.m_carrier != DRW_DwgFramePublication::Carrier::TypedAndRaw || data.m_isEntity
        || data.m_isCustomClass != raw.m_isCustomClass
        || static_cast<bool>(data.m_classStreamOrdinal) != raw.m_isCustomClass
        || data.m_version != raw.m_version || data.m_encodedType != raw.m_objectType
        || data.m_resolvedType != (isRasterDwgDefinition(raw) ? dwgObjType::IMAGEDEF : raw.m_objectType)
        || data.m_recordName != raw.m_recordName
        || data.m_className != raw.m_className || !data.m_hasSourceLocation
        || data.m_sourceOffset != raw.m_objectOffset || !data.m_controlHandles.empty()
        || (data.m_sourceOffsetSpace != DRW_DwgFrameOffsetSpace::PhysicalFile
            && data.m_sourceOffsetSpace != DRW_DwgFrameOffsetSpace::DecodedBuffer)
        || data.m_commonLinkEvidence != raw.m_commonLinkEvidence
        || data.m_commonHandleDataValidated != raw.m_commonHandleDataValidated
        || data.m_numReactors < 0 || data.m_xDictFlag > 1
        || (!legacyUnknown
            && (data.m_parentHandle != raw.m_parentHandle
                || data.m_reactorHandles != raw.m_reactorHandles
                || data.m_numReactors != raw.m_numReactors
                || data.m_xDictHandle != raw.m_xDictHandle || data.m_xDictFlag != raw.m_xDictFlag))
        || cData->m_rasterDwgOrdinals.count(ordinal) != 0u
        || cData->m_rasterDwgLocations.count(location) != 0u
        || !addVectorPayloadBytes(data.m_reactorHandles, bytes)
        || !addStringPayloadBytes(data.m_recordName, bytes)
        || !addStringPayloadBytes(data.m_className, bytes)
        || !addAssociativeRetainedBytes(2u
                                            * (sizeof(dx_data::StandardDwgLocationKey)
                                               + sizeof(std::uint32_t) + 4u * sizeof(void *)),
                                        bytes)
        || cData->m_rasterDwgSourceBytes > ImageDefinitionCaptureMaxRetainedBytes
        || bytes > ImageDefinitionCaptureMaxRetainedBytes - cData->m_rasterDwgSourceBytes) {
        DRW_DBG("Raster DWG publication rejected handle=");
        DRW_DBGH(data.m_handle);
        DRW_DBG(" encoded/resolved/version/carrier/custom=");
        DRW_DBG(data.m_encodedType);
        DRW_DBG("/");
        DRW_DBG(data.m_resolvedType);
        DRW_DBG("/");
        DRW_DBG(static_cast<unsigned>(data.m_version));
        DRW_DBG("/");
        DRW_DBG(static_cast<unsigned>(data.m_carrier));
        DRW_DBG("/");
        DRW_DBG(data.m_isCustomClass);
        DRW_DBG(" class=");
        DRW_DBG(data.m_className);
        DRW_DBG(" rawCommonMatches=");
        DRW_DBG(data.m_parentHandle == raw.m_parentHandle
                && data.m_reactorHandles == raw.m_reactorHandles
                && data.m_numReactors == raw.m_numReactors
                && data.m_xDictHandle == raw.m_xDictHandle
                && data.m_xDictFlag == raw.m_xDictFlag);
        DRW_DBG("\n");
        reject();
        return;
    }
    try {
        frame.publication = data;
        frame.classPublicationAttempt = classAttempt;
        cData->m_rasterDwgOrdinals.emplace(ordinal, data.m_handle);
        cData->m_rasterDwgLocations.emplace(location, data.m_handle);
        frame.publicationSeen = true;
        cData->m_rasterDwgSourceBytes += bytes;
    } catch (...) {
        reject();
    }
}

void dx_iface::finishRasterDwgSources(bool successfulRead, std::size_t appIdBegin, std::size_t layerBegin) noexcept {
    if (cData == nullptr)
        return;
    cData->m_rasterDwgClosedThrough =
        std::max(cData->m_rasterDwgClosedThrough, cData->importGeneration);
    if (cData->m_rasterDwgSourceFailed)
        return;
    const char *capturePhase = "initialization";
    std::uint32_t activeHandle = 0u;
    const auto reject = [this, &capturePhase, &activeHandle]() {
        DRW_DBG("Raster DWG finish-source capture rejected; frames=");
        DRW_DBG(cData->m_rasterDwgSources.size());
        DRW_DBG(" definitions=");
        DRW_DBG(cData->imageDefinitions.size());
        DRW_DBG(" reactors=");
        DRW_DBG(cData->imageDefinitionReactors.size());
        DRW_DBG(" phase=");
        DRW_DBG(capturePhase);
        DRW_DBG(" handle=");
        DRW_DBGH(activeHandle);
        DRW_DBG("\n");
        cData->m_rasterDwgSourceFailed = true;
    };
    // A typed callback without its source carrier must not silently become
    // an authored record when the raw lane is empty.
    const auto hasSources = [this](const auto& records) {
        for (auto item = records.lower_bound({cData->importGeneration, 0u});
             item != records.end() && item->first.first == cData->importGeneration; ++item) {
            if (cData->m_rasterDwgSources.count(item->first) != 1u) return false;
        }
        return true;
    };
    capturePhase = "typed-to-raw source census";
    if (!hasSources(cData->imageDefinitions) || !hasSources(cData->imageDefinitionReactors)) {
        reject();
        return;
    }
    const auto begin = cData->m_rasterDwgSources.lower_bound({cData->importGeneration, 0u});
    if (begin == cData->m_rasterDwgSources.end() || begin->first.first != cData->importGeneration)
        return;
    if (!successfulRead) {
        capturePhase = "reader did not complete";
        reject();
        return;
    }
    try {
        StandardDwgNameIndex appIds, layers;
        const auto nameImport = rasterDwgNameImport(begin->second);
        if (nameImport) {
            const auto index = [](const auto& rows, auto& names) {
                for (const auto& row : rows) names.emplace(row.first, row.second.duplicate ? nullptr : &row.second.name);
            };
            index(nameImport->apps, appIds); index(nameImport->layers, layers);
        } else if (!standardDwgNames(cData->appIds, begin->second.typedBaseline ? begin->second.appIdBegin : appIdBegin, appIds)
            || !standardDwgNames(cData->layers, begin->second.typedBaseline ? begin->second.layerBegin : layerBegin, layers)) {
            capturePhase = "fallback APPID/LAYER census";
            reject();
            return;
        }
        const auto &outcome = cData->dwgReadOutcome;
        DRW_TextCodec codec;
        codec.setVersion(outcome.sourceVersion, false);
        if (outcome.sourceCodePageFieldPresent && outcome.sourceCodePageRecognized) {
            const char *page = dwgCodePageName(outcome.sourceCodePageId);
            if (page == nullptr) {
                capturePhase = "source codepage binding";
                reject();
                return;
            }
            codec.setByteCodePage(page);
            if (outcome.sourceVersion <= DRW::AC1018)
                codec.setCodePage(page, false);
        }
        for (auto current = begin; current != cData->m_rasterDwgSources.end()
                                   && current->first.first == cData->importGeneration;
             ++current) {
            activeHandle = current->first.second;
            capturePhase = "typed callback/publication identity";
            auto &frame = current->second;
            const auto &raw = frame.raw;
            const bool definition = isRasterDwgDefinition(raw);
            const DRW_TableEntry *typed = nullptr;
            const auto def = cData->imageDefinitions.find(current->first);
            const auto reactor = cData->imageDefinitionReactors.find(current->first);
            if (definition && def != cData->imageDefinitions.end())
                typed = &def->second;
            if (!definition && reactor != cData->imageDefinitionReactors.end())
                typed = &reactor->second;
            if (!frame.publicationSeen || frame.generation != current->first.first
                || raw.m_handle != current->first.second || raw.m_version != outcome.sourceVersion
                || typed == nullptr
                || (definition && reactor != cData->imageDefinitionReactors.end())
                || (!definition && def != cData->imageDefinitions.end())
                || (frame.sourceProfileBound
                    && (frame.sourceCodePageId != outcome.sourceCodePageId
                        || frame.sourceCodePageFieldPresent != outcome.sourceCodePageFieldPresent
                        || frame.sourceCodePageRecognized != outcome.sourceCodePageRecognized))) {
                reject();
                return;
            }
            capturePhase = "class-row binding";
            const auto classBinding = rasterClassBinding(frame);
            if (classBinding.state == dx_class_evidence::RasterState::Contradiction) { reject(); return; }
            capturePhase = "name-table import binding";
            if (nameImport && (nameImport->attempt != frame.classReadAttempt || nameImport->version != raw.m_version
                || nameImport->codePage != outcome.sourceCodePageId || nameImport->codePagePresent != outcome.sourceCodePageFieldPresent
                || nameImport->codePageRecognized != outcome.sourceCodePageRecognized)) { reject(); return; }
            const auto visitReactor = [typed](std::uint32_t ordinal, std::uint32_t value,
                    dx_raster_wire::Span, std::uint8_t) noexcept {
                return ordinal < typed->reactorHandles.size() && typed->reactorHandles[ordinal] == value;
            };
            std::size_t dependencyCount = 0u;
            std::size_t stringCount = 0u;
            const auto inspectEed = [typed, &dependencyCount, &stringCount](const dx_raster_wire::EedToken& token) noexcept {
                if (token.index >= typed->extData.size() || !typed->extData[token.index]
                    || typed->extData[token.index]->code() != static_cast<int>(token.code)) return false;
                if (token.code == 1001u || token.code == 1003u) {
                    if (++dependencyCount > StandardDwgObjectCaptureMaxEntries) return false;
                    if (token.code == 1003u && typed->extData[token.index]->rawDwgLayerReference() != token.value) return false;
                }
                if (token.code == 1000u && ++stringCount > StandardDwgObjectCaptureMaxEntries) return false;
                return true;
            };
            capturePhase = "raw IMAGEDEF/reactor wire and EED scan";
            const auto wire = dx_raster_wire::observe(raw.m_rawBytes.data(), raw.m_rawBytes.size(),
                rasterWireRevision(raw.m_version), definition ? dx_raster_wire::Kind::Definition
                    : dx_raster_wire::Kind::Reactor, raw.m_bodyBitSize, visitReactor, inspectEed,
                static_cast<std::uint32_t>(raw.m_objectType));
            if (!rasterWireMatches(wire, *typed, raw.m_objectType, definition)
                || ((wire.status == dx_raster_wire::Status::Proven
                     || wire.status == dx_raster_wire::Status::KnownSoftPointerOwnerBackReference)
                    && wire.eedVariants != typed->extData.size())) {
                DRW_DBG("Raster DWG wire proof mismatch status=");
                DRW_DBG(static_cast<unsigned>(wire.status));
                DRW_DBG(" revision=");
                DRW_DBG(rasterWireRevision(raw.m_version));
                DRW_DBG(" bodyBits=");
                DRW_DBG(raw.m_bodyBitSize);
                DRW_DBG(" eedVariants/typedEed=");
                DRW_DBG(wire.eedVariants);
                DRW_DBG("/");
                DRW_DBG(typed->extData.size());
                DRW_DBG(" ownerRole/value=");
                DRW_DBG(wire.ownerRole);
                DRW_DBG("/");
                DRW_DBGH(wire.owner);
                DRW_DBG(" reactors=");
                DRW_DBG(wire.reactorCount);
                DRW_DBG(" expectedReactors=");
                DRW_DBG(typed->reactorCount());
                DRW_DBG("\n");
                reject();
                return;
            }
            const auto profile = dx_raster_wire::profile(rasterWireRevision(raw.m_version),
                definition ? dx_raster_wire::Kind::Definition : dx_raster_wire::Kind::Reactor, wire);
            std::uint32_t profileIssues = dx_raster_wire::TextSemanticsNotIndependent;
            if (wire.status != dx_raster_wire::Status::Proven
                && wire.status
                    != dx_raster_wire::Status::KnownSoftPointerOwnerBackReference)
                profileIssues |= dx_raster_wire::UnknownWire;
            if (!profile.knownBodyClass) profileIssues |= dx_raster_wire::UnknownBodyClass;
            if (wire.dataStorage) profileIssues |= dx_raster_wire::ExternalDataStorage;
            if (wire.eedLayerEndianConflict) profileIssues |= dx_raster_wire::LayerByteOrderDisagreement;
            if (!outcome.sourceCodePageFieldPresent || !outcome.sourceCodePageRecognized)
                profileIssues |= dx_raster_wire::UnboundCodepage;
            // A matched class row is not qualified source-profile semantics.
            // Keep this issue for every custom class until that separate gate.
            if (raw.m_isCustomClass)
                profileIssues |= dx_raster_wire::ClassEnvelope;
            if (raw.m_isCustomClass && (raw.m_classWasProxy || raw.m_classDwgVersion < 0
                || raw.m_classMaintenanceVersion < 0 || raw.m_classUnknown1 || raw.m_classUnknown2
                || (raw.m_version >= DRW::AC1018 && (raw.m_classProxyFlag & 0x7800u))))
                profileIssues |= dx_raster_wire::ProxyOrUnknownClassMetadata;
            std::vector<dx_data::RasterDwgDependency> dependencies;
            std::vector<dx_raster_wire::EedToken> strings;
            std::size_t dependencyBytes = 0u;
            if (dependencyCount > ImageDefinitionCaptureMaxRetainedBytes / sizeof(dx_data::RasterDwgDependency)
                || !addAssociativeRetainedBytes(dependencyCount * sizeof(dx_data::RasterDwgDependency), dependencyBytes)
                || stringCount > ImageDefinitionCaptureMaxRetainedBytes / sizeof(dx_raster_wire::EedToken)
                || !addAssociativeRetainedBytes(stringCount * sizeof(dx_raster_wire::EedToken), dependencyBytes)
                || cData->m_rasterDwgSourceBytes > ImageDefinitionCaptureMaxRetainedBytes
                || (!frame.typedBaseline && dependencyBytes > ImageDefinitionCaptureMaxRetainedBytes - cData->m_rasterDwgSourceBytes)) {
                capturePhase = "dependency evidence allocation bounds";
                reject(); return;
            }
            dependencies.reserve(dependencyCount);
            strings.reserve(stringCount);
            const char* namePage = raw.m_version > DRW::AC1018 ? "UTF-16"
                : outcome.sourceCodePageFieldPresent && outcome.sourceCodePageRecognized
                    ? dwgCodePageName(outcome.sourceCodePageId) : nullptr;
            const auto captureEed = [&](const dx_raster_wire::EedToken& token) noexcept {
                if (token.code == 1000u) {
                    if (strings.size() >= stringCount) return false;
                    try { strings.push_back(token); return true; } catch (...) { return false; }
                }
                if (token.code != 1001u && token.code != 1003u) return true;
                if (dependencies.size() >= dependencyCount || token.index >= typed->extData.size()) return false;
                try {
                    dx_data::RasterDwgDependency dep;
                    dep.wire = token;
                    const auto& names = token.code == 1003u ? layers : appIds;
                    const auto found = token.value <= (std::numeric_limits<std::uint32_t>::max)()
                        ? names.find(static_cast<std::uint32_t>(token.value)) : names.end();
                    if (found != names.end() && !found->second) return false; // duplicate identity, never guess
                    const auto* value = typed->extData[token.index];
                    if (!value || !value->content.s) return false;
                    if (token.code == 1003u && token.value > (std::numeric_limits<std::uint32_t>::max)())
                        dep.binding = dx_data::RasterDwgDependency::Binding::WideLayer;
                    else if (nameImport) {
                        const auto& events = token.code == 1003u ? nameImport->layers : nameImport->apps;
                        const auto event = events.find(static_cast<std::uint32_t>(token.value));
                        if (event != events.end()) {
                            const auto& row = event->second;
                            if (row.duplicate || row.name != *value->content.s || found == names.end() || *found->second != row.name) return false;
                            dep.read = nameImport; dep.event = &row;
                            dep.binding = row.source && row.source->matches(row.handle, row.name) && namePage
                                && row.source->bound(raw.m_version, namePage) && !row.source->decodeIssues()
                                ? dx_data::RasterDwgDependency::Binding::SourceName : dx_data::RasterDwgDependency::Binding::UnboundNameProfile;
                        }
                    } else if (frame.classReadAttempt != 0u) {
                        // Missing actual-read evidence cannot borrow legacy/advisory snapshots.
                    } else if (token.code == 1003u) {
                        const auto source = cData->m_standardDwgLayerSources.find({frame.generation, static_cast<std::uint32_t>(token.value)});
                        if (source != cData->m_standardDwgLayerSources.end()) {
                            const auto& row = source->second;
                            if (!row || row->name != *value->content.s || found == names.end()
                                || *found->second != row->name) return false;
                            dep.source = row;
                            dep.binding = row->hasUnchangedDwgSourceName() && namePage
                                && row->hasBoundDwgNameProfile(raw.m_version, namePage) && !row->dwgNameDecodeIssues()
                                ? dx_data::RasterDwgDependency::Binding::SourceName
                                : dx_data::RasterDwgDependency::Binding::UnboundNameProfile;
                        }
                    } else {
                        const auto source = cData->m_standardDwgAppIdSources.find({frame.generation, static_cast<std::uint32_t>(token.value)});
                        if (source != cData->m_standardDwgAppIdSources.end()) {
                            const auto& row = source->second;
                            if (!row || row->name != *value->content.s || found == names.end()
                                || *found->second != row->name) return false;
                            dep.source = row;
                            dep.binding = row->hasUnchangedDwgSourceName() && namePage
                                && row->hasBoundDwgNameProfile(raw.m_version, namePage) && !row->dwgNameDecodeIssues()
                                ? dx_data::RasterDwgDependency::Binding::SourceName
                                : dx_data::RasterDwgDependency::Binding::UnboundNameProfile;
                        }
                    }
                    if (!nameImport && frame.classReadAttempt == 0u
                        && dep.binding == dx_data::RasterDwgDependency::Binding::SourceName)
                        dep.binding = dx_data::RasterDwgDependency::Binding::UnboundReadContext;
                    if (dep.binding != dx_data::RasterDwgDependency::Binding::SourceName)
                        profileIssues |= dx_raster_wire::UnboundDependency;
                    dependencies.push_back(std::move(dep));
                    return true;
                } catch (...) { return false; }
            };
            const auto dependencyWire = dependencyCount == 0u ? wire : dx_raster_wire::observe(raw.m_rawBytes.data(), raw.m_rawBytes.size(),
                rasterWireRevision(raw.m_version), definition ? dx_raster_wire::Kind::Definition
                    : dx_raster_wire::Kind::Reactor, raw.m_bodyBitSize, visitReactor, captureEed,
                static_cast<std::uint32_t>(raw.m_objectType));
            if (!dx_raster_wire::sameProof(wire, dependencyWire) || dependencies.size() != dependencyCount
                || strings.size() != stringCount) {
                capturePhase = "EED dependency/source binding";
                reject(); return;
            }
            capturePhase = "independent raw payload reparse";
            codec.resetAccumulatedDecodeIssues();
            dwgBuffer body(raw.m_rawBytes.data(), raw.m_rawBytes.size(), &codec);
            dwgBuffer probe = body.forkIndependent();
            if (probe.getObjType(raw.m_version) != raw.m_objectType || !probe.isGood()) {
                reject();
                return;
            }
            std::unique_ptr<DRW_TableEntry> parsed;
            if (definition) {
                auto value = std::make_unique<StandardDwgPayloadProbe<DRW_ImageDef>>();
                if (!value->parseDwg(raw.m_version, &body, raw.m_bodyBitSize)) {
                    reject();
                    return;
                }
                parsed = std::move(value);
            } else {
                auto value =
                    std::make_unique<StandardDwgPayloadProbe<DRW_ImageDefinitionReactor>>();
                if (!value->parseDwg(raw.m_version, &body, raw.m_bodyBitSize)) {
                    reject();
                    return;
                }
                parsed = std::move(value);
            }
            // Resolve the same source dependency envelope as the original
            // callback. This correlation is not an independent text certificate.
            const auto observed = [](auto, const UTF8STRING &) { return true; };
            capturePhase = "raw-to-typed payload correlation";
            if (!body.isGood()
                || !resolveStandardDwgExtendedData(*parsed, appIds, layers, observed, observed)
                || !rasterDwgModelEqual(*parsed, *typed, raw.m_version, definition)
                || parsed->handle != raw.m_handle
                || parsed->reactorCount() != frame.publication.m_numReactors
                || parsed->extensionDictionaryFlag() != frame.publication.m_xDictFlag
                || parsed->hasDataStorageBinaryData() != raw.m_hasDataStorage
                || (drwDwgCommonLinkEvidenceValidated(raw.m_commonLinkEvidence)
                    && (parsed->parentHandle != raw.m_parentHandle
                        || parsed->reactorHandles != raw.m_reactorHandles
                        || parsed->xDictHandle != raw.m_xDictHandle))) {
                reject();
                return;
            }
            if (frame.typedBaseline) {
                capturePhase = "immutable baseline comparison";
                if (!rasterDwgModelEqual(*frame.typedBaseline, *typed, raw.m_version, definition)
                    || frame.nameImport != nameImport
                    || !frame.classBindingObserved || !dx_class_evidence::sameRasterBinding(frame.classBinding, classBinding)
                    || !frame.wireObserved || !dx_raster_wire::sameProof(frame.wire, wire)
                    || !frame.dependenciesObserved || frame.profileIssues != profileIssues
                    || frame.eedDependencies.size() != dependencies.size() || frame.eedStrings.size() != strings.size()) {
                    reject();
                    return;
                }
                for (std::size_t n = 0; n < dependencies.size(); ++n) {
                    const auto& a = frame.eedDependencies[n]; const auto& b = dependencies[n];
                    if (!dx_raster_wire::sameToken(a.wire, b.wire)
                        || a.binding != b.binding || a.source != b.source || a.read != b.read || a.event != b.event) { reject(); return; }
                }
                for (std::size_t n = 0; n < strings.size(); ++n)
                    if (!dx_raster_wire::sameToken(frame.eedStrings[n], strings[n])) { reject(); return; }
                continue; // Validation must never refresh an established source.
            }
            capturePhase = "immutable baseline capture";
            if ((!outcome.sourceCodePageFieldPresent || !outcome.sourceCodePageRecognized)
                && (raw.m_version <= DRW::AC1018 || !parsed->extData.empty()))
                codec.mergeDecodeIssues(
                    DRW::dxfTextIssueMask(DRW::DxfTextIssue::UnsupportedEncodingProfile));
            std::size_t bytes = 0u;
            if (definition) {
                if (!addImageDefinitionRetainedBytes(dynamic_cast<const DRW_ImageDef &>(*typed),
                                                     bytes)) {
                    reject();
                    return;
                }
            } else {
                bytes = sizeof(DRW_ImageDefinitionReactor) + 2u * sizeof(void *);
                if (!addTableEntryRetainedBytes(*typed, bytes)) {
                    reject();
                    return;
                }
            }
            if (cData->m_rasterDwgSourceBytes > ImageDefinitionCaptureMaxRetainedBytes
                || !addAssociativeRetainedBytes(dependencies.capacity() * sizeof(dx_data::RasterDwgDependency), bytes)
                || !addAssociativeRetainedBytes(strings.capacity() * sizeof(dx_raster_wire::EedToken), bytes)
                || bytes > ImageDefinitionCaptureMaxRetainedBytes - cData->m_rasterDwgSourceBytes) {
                reject();
                return;
            }
            std::shared_ptr<const DRW_TableEntry> snapshot;
            if (definition)
                snapshot = std::make_shared<const DRW_ImageDef>(
                    dynamic_cast<const DRW_ImageDef &>(*typed));
            else
                snapshot = std::make_shared<const DRW_ImageDefinitionReactor>(
                    dynamic_cast<const DRW_ImageDefinitionReactor &>(*typed));
            frame.typedBaseline = std::move(snapshot);
            frame.nameImport = nameImport;
            frame.appIdBegin = appIdBegin; frame.layerBegin = layerBegin;
            frame.classBinding = classBinding;
            frame.classBindingObserved = true;
            frame.wire = wire;
            frame.profile = profile;
            frame.profileIssues = profileIssues;
            frame.eedDependencies = std::move(dependencies);
            frame.eedStrings = std::move(strings);
            frame.dependenciesObserved = true;
            frame.wireObserved = true;
            frame.sourceCodePageId = outcome.sourceCodePageId;
            frame.sourceCodePageFieldPresent = outcome.sourceCodePageFieldPresent;
            frame.sourceCodePageRecognized = outcome.sourceCodePageRecognized;
            frame.sourceProfileBound = true;
            frame.textDecodeObserved = true;
            frame.textDecodeIssues = codec.accumulatedDecodeIssues();
            frame.payloadMatched = true;
            cData->m_rasterDwgSourceBytes += bytes;
        }
    } catch (...) {
        reject();
    }
}

bool dx_iface::hasUnchangedRasterDwgSources() const noexcept {
    if (cData == nullptr)
        return false;
    if (cData->m_rasterDwgSourceFailed) {
        DRW_DBG("Raster DWG source-correlation check: capture was already marked failed\n");
        return false;
    }
    bool dependencies = false;
    for (const auto &source : cData->m_rasterDwgSources) {
        const auto &frame = source.second;
        const bool definition = isRasterDwgDefinition(frame.raw);
        const auto def = cData->imageDefinitions.find(source.first);
        const auto reactor = cData->imageDefinitionReactors.find(source.first);
        const DRW_TableEntry *typed = nullptr;
        if (definition && def != cData->imageDefinitions.end())
            typed = &def->second;
        if (!definition && reactor != cData->imageDefinitionReactors.end())
            typed = &reactor->second;
        const auto mismatch = [&](const char *reason) {
            DRW_DBG("Raster DWG source-correlation mismatch handle=");
            DRW_DBGH(source.first.second);
            DRW_DBG(" kind=");
            DRW_DBG(definition ? "IMAGEDEF: " : "IMAGEDEF_REACTOR: ");
            DRW_DBG(reason);
            DRW_DBG("\n");
            return false;
        };
        if (!typed) return mismatch("typed callback missing");
        if (!frame.typedBaseline) return mismatch("immutable typed snapshot missing");
        if (!frame.sourceProfileBound) return mismatch("source profile not bound");
        if (!frame.payloadMatched) return mismatch("raw payload not correlated");
        if (frame.nameImport != rasterDwgNameImport(frame)) return mismatch("name-table import identity changed");
        if (frame.nameImport && (frame.nameImport->version != frame.raw.m_version
            || frame.nameImport->codePage != frame.sourceCodePageId
            || frame.nameImport->codePagePresent != frame.sourceCodePageFieldPresent
            || frame.nameImport->codePageRecognized != frame.sourceCodePageRecognized))
            return mismatch("name-table import profile changed");
        if (!frame.classBindingObserved
            || !dx_class_evidence::sameRasterBinding(frame.classBinding, rasterClassBinding(frame)))
            return mismatch("class-row binding changed");
        if (!frame.wireObserved || !frame.dependenciesObserved) return mismatch("wire/dependency proof missing");
        if (frame.wire.status == dx_raster_wire::Status::Malformed) return mismatch("wire profile malformed");
        if (frame.wire.status
            == dx_raster_wire::Status::KnownSoftPointerOwnerBackReference)
            return mismatch("IMAGEDEF owner back-reference output behavior is not qualified");
        if (!frame.publicationSeen) return mismatch("frame publication missing");
        if (source.first.first != frame.generation) return mismatch("generation key mismatch");
        if (source.first.second != frame.raw.m_handle) return mismatch("handle key mismatch");
        if (definition && reactor != cData->imageDefinitionReactors.end())
            return mismatch("same handle has a reactor record");
        if (!definition && def != cData->imageDefinitions.end())
            return mismatch("same handle has a definition record");
        if (!rasterDwgModelEqual(*frame.typedBaseline, *typed, frame.raw.m_version, definition))
            return mismatch("typed model differs from immutable snapshot");
        dependencies = dependencies || !frame.eedDependencies.empty();
    }
    if (!dependencies) return true; // Keep the common no-EED check allocation-free.
    try {
        if (cData->appIds.size() > kMaxAdapterBasicTableRecords || cData->layers.size() > kMaxAdapterBasicTableRecords)
            return false;
        std::map<std::uint32_t, const DRW_AppId*> apps;
        std::map<std::uint32_t, const DRW_Layer*> layers;
        using Owner = const DRW_DwgTableNameSource*;
        std::set<Owner> knownApps, knownLayers;
        for (const auto& entry : cData->m_rasterDwgNameImports) {
            const auto& read = entry.second;
            if (!read || !read->closed || !read->valid) continue;
            for (const auto& event : read->apps) if (event.second.source) knownApps.insert(event.second.source.get());
            for (const auto& event : read->layers) if (event.second.source) knownLayers.insert(event.second.source.get());
        }
        std::map<Owner, std::pair<std::size_t, const DRW_AppId*>> appOwners;
        std::map<Owner, std::pair<std::size_t, const DRW_Layer*>> layerOwners;
        std::set<std::uint32_t> unreceiptedApps, unreceiptedLayers;
        for (const auto& row : cData->appIds) {
            const auto inserted = apps.emplace(row.handle, &row);
            if (!inserted.second) inserted.first->second = nullptr;
            const auto owner = row.dwgNameSource().get();
            if (!owner || !knownApps.count(owner)) unreceiptedApps.insert(row.handle);
            else { auto& current = appOwners[owner]; ++current.first; current.second = &row; }
        }
        for (const auto& row : cData->layers) {
            const auto inserted = layers.emplace(row.handle, &row);
            if (!inserted.second) inserted.first->second = nullptr;
            const auto owner = row.dwgNameSource().get();
            if (!owner || !knownLayers.count(owner)) unreceiptedLayers.insert(row.handle);
            else { auto& current = layerOwners[owner]; ++current.first; current.second = &row; }
        }
        for (const auto& source : cData->m_rasterDwgSources) for (const auto& dep : source.second.eedDependencies) {
            if (dep.event) {
                const auto& event = *dep.event;
                if (dep.read != source.second.nameImport || !dep.read || !dep.read->closed || !dep.read->valid
                    || dep.read->attempt != source.second.classReadAttempt || dep.read->generation != source.second.generation
                    || event.duplicate || event.handle != dep.wire.value) return false;
                const auto& events = dep.wire.code == 1001u ? dep.read->apps : dep.read->layers;
                const auto retained = events.find(event.handle);
                if (retained == events.end() || &retained->second != dep.event) return false;
                if (!event.source) continue; // Unknown native name field stays unqualified.
                if (dep.wire.code == 1001u) {
                    const auto current = appOwners.find(event.source.get());
                    if (unreceiptedApps.count(event.handle) || current == appOwners.end() || current->second.first != 1u
                        || current->second.second->handle != event.handle || current->second.second->name != event.name) return false;
                } else if (dep.wire.code == 1003u) {
                    const auto current = layerOwners.find(event.source.get());
                    if (unreceiptedLayers.count(event.handle) || current == layerOwners.end() || current->second.first != 1u
                        || current->second.second->handle != event.handle || current->second.second->name != event.name) return false;
                } else return false;
                continue;
            }
            if (!dep.source) continue; // Permanently unqualified, never filled from later rows.
            if (dep.wire.value > (std::numeric_limits<std::uint32_t>::max)()) return false;
            const auto handle = static_cast<std::uint32_t>(dep.wire.value);
            if (dep.wire.code == 1001u) {
                const auto* original = dynamic_cast<const DRW_AppId*>(dep.source.get());
                const auto current = apps.find(handle);
                if (!original || original->handle != handle || current == apps.end() || !current->second
                    || current->second->name != original->name || !current->second->sameDwgNameSource(*original)) return false;
            } else if (dep.wire.code == 1003u) {
                const auto* original = dynamic_cast<const DRW_Layer*>(dep.source.get());
                const auto current = layers.find(handle);
                if (!original || original->handle != handle || current == layers.end() || !current->second
                    || current->second->name != original->name || !current->second->sameDwgNameSource(*original)) return false;
            } else return false;
        }
    } catch (...) { return false; }
    return true;
}

bool dx_iface::recordOpaqueDwgSourceFrameIdentity(
        const DRW_UnsupportedObject& data) noexcept {
    if (cData == nullptr || !cData->dwgReadOutcome.attempted
        || cData->sourceFormat != dx_source_format::DWG
        || cData->importGeneration == 0u)
        return false;

    dx_dwgReadOutcome& outcome = cData->dwgReadOutcome;
    const auto reject = [&outcome]() {
        outcome.opaqueSourceCaptureFailed = true;
        return false;
    };
    if (outcome.opaqueSourceCaptureFailed
        || data.m_handle == 0u || data.m_handle == DRW::NoHandle
        || rasterWireRevision(data.m_version) == 0u
        || data.m_objectOffset > std::numeric_limits<std::uint32_t>::max()
        || data.m_rawBytes.size() != data.m_objectSize
        || data.m_bodyBitSize
               > static_cast<std::uint64_t>(data.m_objectSize) * 8u)
        return reject();

    const dx_data::StandardDwgFrameKey key{
        cData->importGeneration, data.m_handle};
    if (cData->m_opaqueDwgSourceFrameIdentities.count(key) != 0u
        || cData->m_opaqueDwgSourceFrameIdentities.size()
               >= OpaqueDwgSourceFrameCaptureMaxRecords)
        return reject();
    try {
        const auto inserted =
            cData->m_opaqueDwgSourceFrameIdentities.insert(key);
        if (!inserted.second)
            return reject();
        countDwgReadCallback(outcome.opaqueSourceFramesCaptured);
        return true;
    } catch (...) {
        return reject();
    }
}

bool dx_iface::recordOpaqueDwgOutputQualification(
        std::uint32_t sourceHandle) noexcept {
    if (cData == nullptr || !cData->dwgReadOutcome.attempted
        || cData->sourceFormat != dx_source_format::DWG
        || cData->importGeneration == 0u || sourceHandle == 0u
        || sourceHandle == DRW::NoHandle)
        return false;
    dx_dwgReadOutcome& outcome = cData->dwgReadOutcome;
    const dx_data::StandardDwgFrameKey key{
        cData->importGeneration, sourceHandle};
    if (outcome.opaqueSourceCaptureFailed
        || cData->m_opaqueDwgSourceFrameIdentities.count(key) != 1u)
        return false;
    if (m_pendingOpaqueDwgOutputQualificationFrameIdentities.count(key) == 1u)
        return true;
    if (m_pendingOpaqueDwgOutputQualificationFrameIdentities.size()
        >= OpaqueDwgSourceFrameCaptureMaxRecords)
        return false;
    try {
        // Several independently checked graph proofs can converge on one
        // opaque callback identity. The per-attempt set is idempotent; its
        // membership is committed to dx_data only after the DXF transaction
        // publishes successfully.
        m_pendingOpaqueDwgOutputQualificationFrameIdentities.insert(key);
        return true;
    } catch (...) {
        return false;
    }
}

bool dx_iface::hasCompletePendingOpaqueDwgOutputQualification() const noexcept {
    if (cData == nullptr || !cData->dwgReadOutcome.attempted
        || cData->sourceFormat != dx_source_format::DWG
        || !cData->hasCompleteOpaqueDwgSourceCapture())
        return false;

    const dx_dwgReadOutcome& outcome = cData->dwgReadOutcome;
    if (m_pendingOpaqueDwgOutputQualificationFrameIdentities.size()
        != outcome.opaqueViewCallbacks)
        return false;

    const dx_data::StandardDwgFrameKey first{cData->importGeneration, 0u};
    const auto begin = cData->m_opaqueDwgSourceFrameIdentities.lower_bound(first);
    std::size_t sourceFrames = 0u;
    for (auto current = begin;
         current != cData->m_opaqueDwgSourceFrameIdentities.end()
             && current->first == cData->importGeneration;
         ++current) {
        if (m_pendingOpaqueDwgOutputQualificationFrameIdentities.count(
                *current) != 1u
            || ++sourceFrames > outcome.opaqueViewCallbacks)
            return false;
    }
    for (const OpaqueDwgOutputKey& key :
         m_pendingOpaqueDwgOutputQualificationFrameIdentities) {
        if (key.first != cData->importGeneration
            || cData->m_opaqueDwgSourceFrameIdentities.count(key) != 1u)
            return false;
    }
    return sourceFrames == outcome.opaqueViewCallbacks;
}

bool dx_iface::retainOpaqueDwgSourceFrame(
        const DRW_UnsupportedObject& data) noexcept {
    if (cData == nullptr || !cData->dwgReadOutcome.attempted
        || cData->sourceFormat != dx_source_format::DWG
        || cData->importGeneration == 0u)
        return false;

    const auto reject = [this]() {
        cData->dwgReadOutcome.opaqueSourceCaptureFailed = true;
        return false;
    };
    dx_dwgReadOutcome& outcome = cData->dwgReadOutcome;
    if (outcome.opaqueSourceCaptureFailed)
        return false;
    if (data.m_handle == 0u || data.m_handle == DRW::NoHandle
        || rasterWireRevision(data.m_version) == 0u
        || data.m_objectOffset > std::numeric_limits<std::uint32_t>::max()
        || data.m_rawBytes.size() != data.m_objectSize
        || data.m_bodyBitSize
               > static_cast<std::uint64_t>(data.m_objectSize) * 8u)
        return reject();

    const dx_data::StandardDwgFrameKey key{
        cData->importGeneration, data.m_handle};
    if (cData->m_opaqueDwgSourceFrames.count(key) != 0u
        || cData->m_opaqueDwgSourceFrameIdentities.count(key) != 0u
        || cData->m_opaqueDwgSourceFrames.size()
               >= OpaqueDwgSourceFrameCaptureMaxRecords)
        return reject();

    std::size_t estimate = 0u;
    const std::size_t mapNodeOverhead = sizeof(
        std::pair<const dx_data::StandardDwgFrameKey,
                  DRW_UnsupportedObject>)
        - sizeof(DRW_UnsupportedObject) + 4u * sizeof(void*);
    if (!estimateAcDsHistoryDwgFrameBytes(data, estimate)
        || !addAssociativeRetainedBytes(mapNodeOverhead, estimate)
        || cData->m_opaqueDwgSourceFrameRetainedBytes
               > OpaqueDwgSourceFrameCaptureMaxRetainedBytes
        || estimate > OpaqueDwgSourceFrameCaptureMaxRetainedBytes
               - cData->m_opaqueDwgSourceFrameRetainedBytes)
        return reject();

    try {
        const auto inserted = cData->m_opaqueDwgSourceFrames.emplace(key, data);
        if (!inserted.second)
            return reject();
        cData->m_opaqueDwgSourceFrameRetainedBytes += estimate;
        if (!recordOpaqueDwgSourceFrameIdentity(data)) {
            cData->m_opaqueDwgSourceFrames.erase(key);
            cData->m_opaqueDwgSourceFrameRetainedBytes -= estimate;
            return false;
        }
        if (data.m_version == DRW::AC1024 && typeid(*this) == typeid(dx_iface)
            && m_classEvidenceReadData == cData && m_classEvidenceReadAttempt != 0u
            && cData->m_classEvidenceOwner == this
            && cData->m_classEvidenceAttempt == m_classEvidenceReadAttempt
            && cData->m_classEvidenceGeneration == cData->importGeneration
            && (data.m_recordName == "RENDERGLOBAL" || data.m_recordName == "MENTALRAYRENDERSETTINGS")) {
            const auto selected = std::find(ac1024DwgRenderHandles.begin(), ac1024DwgRenderHandles.end(),
                                            data.m_handle);
            if (selected != ac1024DwgRenderHandles.end()) {
                const auto index = static_cast<std::size_t>(selected - ac1024DwgRenderHandles.begin());
                if (data.m_rawBytes.size() == ac1024DwgRenderBodySizes[index]) {
                    // Retain the original text-bearing body separately from
                    // the editable typed models and correlated frame view.
                    try { m_dwgRenderBodyBaselines[index] = data.m_rawBytes; }
                    catch (...) { m_dwgRenderBodyBaselines[index].clear(); }
                }
            }
        }
        return true;
    } catch (...) {
        return reject();
    }
}

void dx_iface::retainStandardDwgObjectFrame(const DRW_UnsupportedObject& data) {
    if (cData == nullptr || cData->m_standardDwgObjectCaptureFailed)
        return;
    const auto reject = [this]() { rejectStandardDwgObjectCapture(); };
    // Legacy shared prologues do not publish a decoded common-handle tail.
    // Preserve that explicit Unknown state for source correlation only; it
    // cannot authorize semantic output or become a validated absent owner.
    const bool legacyUnknownLinks = data.m_version <= DRW::AC1018
        && data.m_commonLinkEvidence == DRW_DwgCommonLinkEvidence::Unknown
        && !data.m_commonHandleDataValidated;
    if (!cData->dwgReadOutcome.attempted
        || cData->sourceFormat != dx_source_format::DWG
        || cData->importGeneration == 0
        || !isStandardDwgObjectType(data.m_objectType)
        || data.m_version < DRW::AC1012 || data.m_version > DRW::AC1032
        || data.m_handle == 0 || data.m_handle == DRW::NoHandle
        || data.m_isEntity || data.m_isCustomClass || data.m_hasClassDefinition
        || !data.m_recordName.empty() || !data.m_className.empty()
        || !data.m_classAppName.empty()
        || (!legacyUnknownLinks
            && (!drwDwgCommonLinkEvidenceValidated(data.m_commonLinkEvidence)
                || !data.m_commonHandleDataValidated))
        || data.m_numReactors < 0
        || static_cast<std::size_t>(data.m_numReactors) != data.m_reactorHandles.size()
        || data.m_xDictFlag > 1
        || data.m_rawBytes.empty() || data.m_rawBytes.size() != data.m_objectSize
        || data.m_objectOffset > std::numeric_limits<std::uint32_t>::max()
        || data.m_bodyBitSize > static_cast<std::uint64_t>(data.m_objectSize) * 8u
        || cData->m_standardDwgAppIdSources.size() + cData->m_standardDwgLayerSources.size()
            >= StandardDwgObjectCaptureMaxRecords
        || cData->m_standardDwgObjectFrames.size() >= StandardDwgObjectCaptureMaxRecords
            - cData->m_standardDwgAppIdSources.size() - cData->m_standardDwgLayerSources.size()
        || cData->dwgReadOutcome.standardObjectFramesCaptured >= StandardDwgObjectCaptureMaxRecords
        || cData->m_standardDwgObjectFrames.count(
            {cData->importGeneration, data.m_handle}) != 0u
        || cData->m_standardDwgAppIdSources.count(
            {cData->importGeneration, data.m_handle}) != 0u
        || cData->m_standardDwgLayerSources.count(
            {cData->importGeneration, data.m_handle}) != 0u) {
        reject();
        return;
    }
    std::size_t estimate = 0u;
    if (!estimateAcDsHistoryDwgFrameBytes(data, estimate)
        || !addAssociativeSlotBytes(1u,
            sizeof(std::pair<const dx_data::StandardDwgFrameKey, dx_data::StandardDwgObjectFrame>)
                - sizeof(DRW_UnsupportedObject) + 4u * sizeof(void*), estimate)
        || !standardDwgCaptureFits(cData->m_standardDwgObjectRetainedBytes, estimate)) {
        reject();
        return;
    }
    try {
        dx_data::StandardDwgObjectFrame frame;
        frame.raw = data;
        frame.generation = cData->importGeneration;
        cData->m_standardDwgObjectFrames.emplace(
            dx_data::StandardDwgFrameKey{cData->importGeneration, data.m_handle},
            std::move(frame));
        cData->m_standardDwgObjectRetainedBytes += estimate;
        if (!recordOpaqueDwgSourceFrameIdentity(data)) {
            cData->m_standardDwgObjectFrames.erase(
                {cData->importGeneration, data.m_handle});
            cData->m_standardDwgObjectRetainedBytes -= estimate;
            reject();
            return;
        }
        countDwgReadCallback(cData->dwgReadOutcome.standardObjectFramesCaptured);
    } catch (...) {
        reject();
    }
}

bool dx_iface::retainDwgPlotSettingsPublication(
        const DRW_DwgFramePublication& publication) noexcept {
    if (cData == nullptr || !cData->dwgReadOutcome.attempted
        || cData->sourceFormat != dx_source_format::DWG
        || cData->importGeneration == 0u)
        return false;
    const auto reject = [this]() {
        cData->m_dwgPlotSettingsSourceCaptureFailed = true;
        cData->plotSettingsCaptureFailed = true;
        return false;
    };
    if (cData->m_dwgPlotSettingsSourceCaptureFailed
        || publication.m_version < DRW::AC1015
        || publication.m_version > DRW::AC1027
        || publication.m_handle == 0u
        || publication.m_handle == DRW::NoHandle
        || !publication.m_hasSourceLocation
        || publication.m_sourceOffset
            > (std::numeric_limits<std::uint32_t>::max)()
        || (publication.m_sourceOffsetSpace
                != DRW_DwgFrameOffsetSpace::PhysicalFile
            && publication.m_sourceOffsetSpace
                != DRW_DwgFrameOffsetSpace::DecodedBuffer)
        || publication.m_encodedType < 500
        || publication.m_resolvedType != publication.m_encodedType
        || publication.m_isEntity || !publication.m_isCustomClass
        || publication.m_carrier
            != DRW_DwgFramePublication::Carrier::TypedAndRaw
        || publication.m_recordName != "PLOTSETTINGS"
        || publication.m_className != "AcDbPlotSettings"
        || !publication.m_classStreamOrdinal.has_value()
        || publication.m_numReactors < 0 || publication.m_xDictFlag > 1u
        || !publication.m_controlHandles.empty()) {
        return reject();
    }

    const dx_data::StandardDwgFrameKey key{
        cData->importGeneration, publication.m_handle};
    const auto typed = cData->m_dwgPlotSettingsSources.find(key);
    const auto raw = cData->m_opaqueDwgSourceFrames.find(key);
    if (typed == cData->m_dwgPlotSettingsSources.end()
        || raw == cData->m_opaqueDwgSourceFrames.end()
        || typed->second.publicationSeen) {
        return reject();
    }
    const DRW_UnsupportedObject& sourceRaw = raw->second;
    const DRW_PlotSettings& source = typed->second.typedBaseline;
    if (source.handle != publication.m_handle
        || source.tType != DRW::PLOTSETTINGS
        || sourceRaw.m_handle != publication.m_handle
        || sourceRaw.m_version != publication.m_version
        || sourceRaw.m_objectType != publication.m_encodedType
        || !sourceRaw.m_isCustomClass || sourceRaw.m_isEntity
        || !sourceRaw.m_hasClassDefinition
        || sourceRaw.m_recordName != publication.m_recordName
        || sourceRaw.m_className != publication.m_className
        || sourceRaw.m_objectOffset != publication.m_sourceOffset
        || sourceRaw.m_objectSize != sourceRaw.m_rawBytes.size()
        || sourceRaw.m_rawBytes.empty()
        || sourceRaw.m_bodyBitSize
            > static_cast<std::uint64_t>(sourceRaw.m_objectSize) * 8u
        || sourceRaw.m_commonLinkEvidence
            != publication.m_commonLinkEvidence
        || sourceRaw.m_commonHandleDataValidated
            != publication.m_commonHandleDataValidated) {
        return reject();
    }

    const bool commonValidated = drwDwgCommonLinkEvidenceValidated(
        publication.m_commonLinkEvidence);
    if (commonValidated) {
        if (sourceRaw.m_parentHandle != publication.m_parentHandle
            || sourceRaw.m_reactorHandles != publication.m_reactorHandles
            || sourceRaw.m_numReactors != publication.m_numReactors
            || sourceRaw.m_xDictHandle != publication.m_xDictHandle
            || sourceRaw.m_xDictFlag != publication.m_xDictFlag
            || source.parentHandle != publication.m_parentHandle
            || source.reactorHandles != publication.m_reactorHandles
            || source.reactorCount() != publication.m_numReactors
            || source.xDictHandle != publication.m_xDictHandle
            || source.extensionDictionaryFlag() != publication.m_xDictFlag) {
            return reject();
        }
    } else if (publication.m_commonLinkEvidence
                   != DRW_DwgCommonLinkEvidence::Unknown
               || publication.m_commonHandleDataValidated
               || sourceRaw.m_commonHandleDataValidated) {
        return reject();
    }

    for (const auto& existing : cData->m_dwgPlotSettingsSources) {
        if (existing.first.first != cData->importGeneration)
            continue;
        if (existing.second.publicationSeen
            && (existing.second.publication.m_sourceMapOrdinal
                    == publication.m_sourceMapOrdinal
                || (existing.second.publication.m_sourceOffsetSpace
                        == publication.m_sourceOffsetSpace
                    && existing.second.publication.m_sourceOffset
                        == publication.m_sourceOffset))) {
            return reject();
        }
    }

    // The publication's inline object storage is included in the source-map
    // node estimate captured with the typed baseline. Charge only its dynamic
    // members here.
    std::size_t retainedBytes = 0u;
    if (!addVectorPayloadBytes(publication.m_reactorHandles, retainedBytes)
        || !addVectorPayloadBytes(publication.m_controlHandles, retainedBytes)
        || !addStringPayloadBytes(publication.m_recordName, retainedBytes)
        || !addStringPayloadBytes(publication.m_className, retainedBytes)
        || cData->plotSettingsRetainedBytes
            > PlotSettingsCaptureMaxRetainedBytes
        || retainedBytes > PlotSettingsCaptureMaxRetainedBytes
            - cData->plotSettingsRetainedBytes) {
        return reject();
    }
    try {
        typed->second.publication = publication;
        typed->second.publicationSeen = true;
        cData->plotSettingsRetainedBytes += retainedBytes;
        cData->m_dwgPlotSettingsSourceRetainedBytes += retainedBytes;
        return true;
    } catch (...) {
        return reject();
    }
}

void dx_iface::addDwgAc1024LayerSource(
        const DRW_DwgAc1024LayerSource& source) noexcept {
    if (!cData || typeid(*this) != typeid(dx_iface)
        || source.m_raw.m_version != DRW::AC1024
        || cData->sourceFormat != dx_source_format::DWG
        || m_classEvidenceReadData != cData || !m_classEvidenceReadAttempt
        || cData->m_classEvidenceOwner != this
        || cData->m_classEvidenceAttempt != m_classEvidenceReadAttempt
        || cData->importGeneration != cData->m_classEvidenceGeneration
        || cData->m_ac1024LayerEvidenceFailed)
        return;
    try {
        if (source.m_raw.m_handle == 0u || source.m_raw.m_handle == DRW::NoHandle
            || source.m_raw.m_objectType != 51
            || source.m_raw.m_rawBytes.empty()
            || source.m_raw.m_rawBytes.size() > 1024u
            || source.m_raw.m_objectSize != source.m_raw.m_rawBytes.size()
            || source.m_sourceOffset != source.m_raw.m_objectOffset
            || source.m_sourceOffsetSpace == DRW_DwgFrameOffsetSpace::Unknown
            || cData->m_ac1024LayerSources.size() >= 2u
            || !cData->m_ac1024LayerSources.emplace(source.m_raw.m_handle, source).second) {
            cData->m_ac1024LayerEvidenceFailed = true;
            cData->m_ac1024LayerSources.clear();
            return;
        }
        cData->m_ac1024LayerGeneration = cData->importGeneration;
    } catch (...) {
        cData->m_ac1024LayerEvidenceFailed = true;
        cData->m_ac1024LayerSources.clear();
    }
}

void dx_iface::addDwgAc1024LayerControlSource(
        const DRW_DwgAc1024LayerControlSource& source) noexcept {
    const auto reject = [this]() noexcept {
        m_dwgLayerControlSourceProof.reset();
        m_dwgLayerControlSourceOwner = cData;
        m_dwgLayerControlSourceGeneration =
            cData == nullptr ? 0u : cData->importGeneration;
        m_dwgLayerControlSourceCaptureFailed = true;
    };
    if (cData == nullptr || typeid(*this) != typeid(dx_iface)
        || source.m_raw.m_version != DRW::AC1024
        || cData->sourceFormat != dx_source_format::DWG
        || m_classEvidenceReadData != cData || !m_classEvidenceReadAttempt
        || cData->m_classEvidenceOwner != this
        || cData->m_classEvidenceAttempt != m_classEvidenceReadAttempt
        || cData->importGeneration != cData->m_classEvidenceGeneration
        || cData->m_dwgLayerControlCaptureFailed
        || !cData->m_dwgLayerControlPublicationSeen
        || cData->m_dwgLayerControlGeneration != cData->importGeneration
        || source.m_raw.m_rawBytes.empty()
        || source.m_raw.m_rawBytes.size() > 4096u
        || source.m_raw.m_objectSize != source.m_raw.m_rawBytes.size()
        || source.m_sourceOffset != source.m_raw.m_objectOffset
        || (source.m_sourceOffsetSpace
                != DRW_DwgFrameOffsetSpace::PhysicalFile
            && source.m_sourceOffsetSpace
                != DRW_DwgFrameOffsetSpace::DecodedBuffer)
        || !source.matchesAc1024LayerControlFrame(
            cData->m_dwgLayerControlPublication)) {
        reject();
        return;
    }
    if (m_dwgLayerControlSourceOwner == cData
        && m_dwgLayerControlSourceGeneration == cData->importGeneration
        && (m_dwgLayerControlSourceProof.has_value()
            || m_dwgLayerControlSourceCaptureFailed)) {
        reject();
        return;
    }
    try {
        m_dwgLayerControlSourceProof = source;
        m_dwgLayerControlSourceOwner = cData;
        m_dwgLayerControlSourceGeneration = cData->importGeneration;
        m_dwgLayerControlSourceCaptureFailed = false;
    } catch (...) {
        reject();
    }
}

std::uint64_t dx_iface::aerialMaterialAppIdClassAttempt() const noexcept {
    if (cData == nullptr || cData->sourceFormat != dx_source_format::DWG
        || cData->sourceVersion != DRW::AC1024
        || cData->importGeneration == 0u)
        return 0u;
    const auto found = cData->m_classEvidenceImports.find(
        cData->importGeneration);
    if (found == cData->m_classEvidenceImports.end()
        || !found->second.closed
        || found->second.result.state != dx_class_evidence::State::Joined
        || found->second.result.version != DRW::AC1024
        || found->second.result.generation != cData->importGeneration
        || found->second.result.attempt == 0u)
        return 0u;
    return found->second.result.attempt;
}

void dx_iface::finishAerialMaterialAppIdSource(bool success) noexcept {
    const auto attempt = success ? aerialMaterialAppIdClassAttempt() : 0u;
    const auto bind = [this, attempt](DwgAerialMaterialAppIdFrame& proof) {
        if (attempt == 0u || cData == nullptr || proof.failed
            || !proof.rawSeen || !proof.publicationSeen
            || proof.owner != cData
            || proof.generation != cData->importGeneration
            || (proof.attempt != 0u && proof.attempt != attempt)) {
            proof.failed = true;
            return;
        }
        proof.attempt = attempt;
    };
    bind(m_dwgAerialMaterialAppId);
    bind(m_dwgAerialMaterialAppIdControl);
}

bool dx_iface::wantsDwgAc1024AppIdSource(
        std::uint32_t handle) const noexcept {
    return typeid(*this) == typeid(dx_iface) && cData != nullptr
        && cData->importGeneration != 0u && handle == 0x12u;
}

void dx_iface::addDwgAc1024AppIdSource(
        const DRW_DwgAc1024AppIdSource& source) noexcept {
    auto& proof = m_dwgAerialMaterialAppId;
    const auto reject = [&proof]() noexcept {
        proof = {};
        proof.failed = true;
    };
    if (!wantsDwgAc1024AppIdSource(source.m_raw.m_handle)
        || !cData->dwgReadOutcome.attempted
        || cData->sourceFormat != dx_source_format::DWG
        || proof.rawSeen || proof.failed
        || source.m_raw.m_version != DRW::AC1024
        || source.m_raw.m_objectType != DRW::DwgAppIdObjectType
        || source.m_raw.m_recordName != "AppId"
        || source.m_raw.m_isEntity || source.m_raw.m_isCustomClass
        || source.m_raw.m_hasClassDefinition
        || source.m_raw.m_rawBytes.empty()
        || source.m_raw.m_rawBytes.size() > 4096u
        || source.m_raw.m_objectSize != source.m_raw.m_rawBytes.size()
        || source.m_raw.m_objectOffset != source.m_sourceOffset
        || source.m_raw.m_bodyBitSize
            > static_cast<std::uint64_t>(source.m_raw.m_objectSize) * 8u
        || (source.m_sourceOffsetSpace != DRW_DwgFrameOffsetSpace::PhysicalFile
            && source.m_sourceOffsetSpace != DRW_DwgFrameOffsetSpace::DecodedBuffer)) {
        reject();
        return;
    }
    try {
        proof.owner = cData;
        proof.generation = cData->importGeneration;
        const auto attempt = aerialMaterialAppIdClassAttempt();
        if (attempt != 0u)
            proof.attempt = attempt;
        proof.raw = source.m_raw;
        proof.sourceOffset = source.m_sourceOffset;
        proof.sourceMapOrdinal = source.m_sourceMapOrdinal;
        proof.sourceOffsetSpace = source.m_sourceOffsetSpace;
        proof.rawSeen = true;
    } catch (...) {
        reject();
    }
}

