void dx_iface::retainAerialMaterialAppIdPublication(
        const DRW_DwgFramePublication& publication) noexcept {
    if (cData == nullptr || typeid(*this) != typeid(dx_iface)
        || publication.m_version != DRW::AC1024
        || (publication.m_handle != 0x12u && publication.m_handle != 0x09u))
        return;
    const bool appId = publication.m_handle == 0x12u;
    auto& proof = appId ? m_dwgAerialMaterialAppId
                        : m_dwgAerialMaterialAppIdControl;
    if (proof.publicationSeen || proof.failed) {
        proof.failed = true;
        return;
    }
    proof.owner = cData;
    proof.generation = cData->importGeneration;
    proof.attempt = aerialMaterialAppIdClassAttempt();
    try {
        proof.publication = publication;
        proof.publicationSeen = true;
    } catch (...) {
        proof.failed = true;
    }
}

bool dx_iface::hasQualifiedAerialMaterialAppIdSource() const noexcept {
    if (cData == nullptr || typeid(*this) != typeid(dx_iface)
        || cData->sourceFormat != dx_source_format::DWG
        || cData->sourceVersion != DRW::AC1024
        || cData->importGeneration == 0u
        || aerialMaterialAppIdClassAttempt() == 0u
        || !hasQualifiedDwgStandardAppIdSource(0x12u, "ACAD"))
        return false;
    const auto expectedAttempt = aerialMaterialAppIdClassAttempt();
    const auto valid = [this, expectedAttempt](const DwgAerialMaterialAppIdFrame& proof,
                              std::uint32_t handle, std::int16_t objectType,
                              std::string_view recordName,
                              DRW_DwgFramePublication::Carrier carrier) {
        const auto& raw = proof.raw;
        const auto& event = proof.publication;
        return !proof.failed && proof.owner == cData
            && proof.generation == cData->importGeneration
            && proof.attempt == expectedAttempt
            && proof.rawSeen && proof.publicationSeen
            && proof.sourceOffsetSpace != DRW_DwgFrameOffsetSpace::Unknown
            && raw.m_version == DRW::AC1024 && raw.m_handle == handle
            && raw.m_objectType == objectType && raw.m_recordName == recordName
            && !raw.m_isEntity && !raw.m_isCustomClass
            && !raw.m_hasClassDefinition && !raw.m_rawBytes.empty()
            && raw.m_rawBytes.size() <= 4096u
            && raw.m_objectSize == raw.m_rawBytes.size()
            && raw.m_objectOffset == proof.sourceOffset
            && raw.m_bodyBitSize <= raw.m_rawBytes.size() * 8u
            && event.m_version == DRW::AC1024 && event.m_handle == handle
            && event.m_encodedType == objectType
            && event.m_resolvedType == objectType
            && !event.m_isEntity && !event.m_isCustomClass
            && event.m_recordName == recordName
            && event.m_carrier == carrier && event.m_hasSourceLocation
            && event.m_sourceOffset == proof.sourceOffset
            && event.m_sourceMapOrdinal == proof.sourceMapOrdinal
            && event.m_sourceOffsetSpace == proof.sourceOffsetSpace;
    };
    const auto& appId = m_dwgAerialMaterialAppId;
    const auto& control = m_dwgAerialMaterialAppIdControl;
    if (!valid(appId, 0x12u, DRW::DwgAppIdObjectType, "AppId",
               DRW_DwgFramePublication::Carrier::Typed)
        || !valid(control, 0x09u, DRW::DwgAppIdControlObjectType,
                  "APPID_CONTROL", DRW_DwgFramePublication::Carrier::Control))
        return false;
    const auto& appPublication = appId.publication;
    const auto& controlPublication = control.publication;
    if (appPublication.m_parentHandle != appId.raw.m_parentHandle
        || appPublication.m_reactorHandles != appId.raw.m_reactorHandles
        || appPublication.m_numReactors != appId.raw.m_numReactors
        || appPublication.m_xDictFlag != appId.raw.m_xDictFlag
        || appPublication.m_xDictHandle != appId.raw.m_xDictHandle
        || appPublication.m_commonLinkEvidence != appId.raw.m_commonLinkEvidence
        || appPublication.m_commonHandleDataValidated
            != appId.raw.m_commonHandleDataValidated
        || std::count(controlPublication.m_controlHandles.begin(),
                      controlPublication.m_controlHandles.end(), 0x12u) != 1
        || (appId.sourceMapOrdinal == control.sourceMapOrdinal)
        || (appId.sourceOffsetSpace == control.sourceOffsetSpace
            && appId.sourceOffset == control.sourceOffset))
        return false;
    return true;
}

bool dx_iface::hasCurrentDwgLayerControlSourceProof(
        const dx_data& data) const noexcept {
    if (data.sourceFormat != dx_source_format::DWG
        || data.sourceVersion != DRW::AC1024
        || data.importGeneration == 0u
        || m_dwgLayerControlSourceCaptureFailed
        || m_dwgLayerControlSourceOwner != &data
        || m_dwgLayerControlSourceGeneration != data.importGeneration
        || !m_dwgLayerControlSourceProof.has_value()
        || !data.m_dwgLayerControlPublicationSeen
        || data.m_dwgLayerControlGeneration != data.importGeneration)
        return false;
    const DRW_DwgAc1024LayerControlSource& source =
        *m_dwgLayerControlSourceProof;
    return source.matchesAc1024LayerControlFrame(
        data.m_dwgLayerControlPublication);
}

void dx_iface::addDwgFramePublication(const DRW_DwgFramePublication& data) {
    if (cData == nullptr || !cData->dwgReadOutcome.attempted)
        return;
    retainAerialMaterialAppIdPublication(data);
    retainAerialDwgGlobalMaterialEedPublication(data);
    retainAerialDwgOtherMaterialEedPublication(data);
    retainAerialDwgMLeaderPublication(data);
    retainAerialDwgTableStylePublication(data);
    retainAerialDwgVisualStylePublication(data);
    retainAerialDwgByBlockMaterialPublication(data);
    if (typeid(*this) == typeid(dx_iface) && m_classEvidenceReadData == cData
        && m_classEvidenceReadAttempt && cData->importGeneration == cData->m_classEvidenceGeneration
        && data.m_version == DRW::AC1027 && data.m_encodedType == 51) {
        auto& proof = cData->m_ac1027LayerPublication;
        if (proof.valid) proof.duplicate = true;
        else {
            proof.handle = data.m_handle; proof.offset = data.m_sourceOffset;
            proof.ordinal = data.m_sourceMapOrdinal; proof.space = data.m_sourceOffsetSpace;
            proof.generation = cData->importGeneration;
            proof.valid = data.m_hasSourceLocation && data.m_resolvedType == 51
                && !data.m_isEntity && !data.m_isCustomClass && data.m_recordName == "layer"
                && data.m_carrier == DRW_DwgFramePublication::Carrier::Typed;
            if (!proof.valid) proof.duplicate = true;
        }
    }
    if (typeid(*this) == typeid(dx_iface) && m_classEvidenceReadData == cData
        && m_classEvidenceReadAttempt && cData->importGeneration == cData->m_classEvidenceGeneration
        && data.m_version == DRW::AC1024 && data.m_encodedType == 51
        && !cData->m_ac1024LayerEvidenceFailed) {
        try {
            dx_data::Ac1024LayerPublication proof;
            proof.handle = data.m_handle; proof.offset = data.m_sourceOffset;
            proof.ordinal = data.m_sourceMapOrdinal; proof.space = data.m_sourceOffsetSpace;
            proof.generation = cData->importGeneration;
            proof.valid = data.m_hasSourceLocation && data.m_resolvedType == 51
                && !data.m_isEntity && !data.m_isCustomClass && data.m_recordName == "layer"
                && data.m_carrier == DRW_DwgFramePublication::Carrier::Typed
                && proof.handle != 0u && proof.handle != DRW::NoHandle
                && proof.space != DRW_DwgFrameOffsetSpace::Unknown;
            if (!proof.valid || cData->m_ac1024LayerPublications.size() >= 2u
                || !cData->m_ac1024LayerPublications.emplace(proof.handle, proof).second) {
                cData->m_ac1024LayerEvidenceFailed = true;
                cData->m_ac1024LayerPublications.clear();
            }
        } catch (...) {
            cData->m_ac1024LayerEvidenceFailed = true;
            cData->m_ac1024LayerPublications.clear();
        }
    }
    // Keep SCALE's publication only when it was observed in the actual active
    // class-read attempt. A raw class name/generation alone cannot establish
    // which CLASSES row this frame used. This receipt never admits output.
    if (data.m_version == DRW::AC1024
        && (data.m_recordName == "SCALE" || data.m_className == "AcDbScale")) {
        const auto rejectScale = [this]() noexcept {
            m_dwgLayerStateScaleCaptureFailed = true;
            m_dwgLayerStateScalePublications.clear();
        };
        if (m_dwgLayerStateScaleCaptureFailed
            || typeid(*this) != typeid(dx_iface)
            || m_classEvidenceReadData != cData || !m_classEvidenceReadAttempt
            || cData->m_classEvidenceOwner != this
            || cData->m_classEvidenceAttempt != m_classEvidenceReadAttempt
            || cData->m_classEvidenceGeneration != cData->importGeneration
            || (m_dwgLayerStateScaleSourceOwner != nullptr
                && m_dwgLayerStateScaleSourceOwner != cData)
            || data.m_handle == 0u || !data.m_hasSourceLocation
            || (data.m_sourceOffsetSpace != DRW_DwgFrameOffsetSpace::PhysicalFile
                && data.m_sourceOffsetSpace != DRW_DwgFrameOffsetSpace::DecodedBuffer)
            || data.m_numReactors < 0 || data.m_reactorHandles.size() > 16u
            || static_cast<std::size_t>(data.m_numReactors) != data.m_reactorHandles.size()
            || !data.m_controlHandles.empty()
            || data.m_isEntity || !data.m_isCustomClass
            || data.m_recordName != "SCALE" || data.m_className != "AcDbScale"
            || data.m_carrier != DRW_DwgFramePublication::Carrier::TypedAndRaw
            || data.m_encodedType < 500 || data.m_resolvedType != data.m_encodedType
            || !data.m_classStreamOrdinal.has_value()
            || m_dwgLayerStateScalePublications.size() >= 4096u) {
            rejectScale();
        } else {
            try {
                DwgClassObjectPublication receipt;
                receipt.publication = data;
                receipt.generation = cData->importGeneration;
                receipt.attempt = m_classEvidenceReadAttempt;
                m_dwgLayerStateScaleSourceOwner = cData;
                if (!m_dwgLayerStateScalePublications.emplace(
                        data.m_handle, std::move(receipt)).second)
                    rejectScale();
            } catch (...) { rejectScale(); }
        }
    }
    const auto render = std::find(ac1024DwgRenderHandles.begin(), ac1024DwgRenderHandles.end(), data.m_handle);
    if (data.m_version == DRW::AC1024 && render != ac1024DwgRenderHandles.end()) {
        const bool global = data.m_handle == 0x237u;
        const char* name = global ? "RENDERGLOBAL" : "MENTALRAYRENDERSETTINGS";
        const char* className = global ? "AcDbRenderGlobal" : "AcDbMentalRayRenderSettings";
        if (data.m_recordName == name || data.m_className == className) {
            auto& receipt = m_dwgRenderPublications[static_cast<std::size_t>(
                render - ac1024DwgRenderHandles.begin())];
            const bool first = receipt.generation == 0u
                && (m_dwgRenderReadOwner == nullptr || m_dwgRenderReadOwner == cData);
            if (m_dwgRenderReadOwner == nullptr)
                m_dwgRenderReadOwner = cData;
            receipt = {};
            receipt.generation = cData->importGeneration;
            if (first && typeid(*this) == typeid(dx_iface)
                && m_classEvidenceReadData == cData && m_classEvidenceReadAttempt != 0u
                && cData->m_classEvidenceOwner == this
                && cData->m_classEvidenceAttempt == m_classEvidenceReadAttempt
                && cData->m_classEvidenceGeneration == cData->importGeneration
                && data.m_recordName == name && data.m_className == className
                && data.m_reactorHandles.size() == 1u && data.m_controlHandles.empty()) {
                try {
                    receipt.publication = data;
                    receipt.attempt = m_classEvidenceReadAttempt;
                } catch (...) { receipt.attempt = 0u; }
            }
        }
    }
    const auto index = static_cast<std::size_t>(data.m_carrier);
    if (index < cData->dwgReadOutcome.observedReceiptCarriers.size())
        countDwgReadCallback(cData->dwgReadOutcome.observedReceiptCarriers[index]);
    if (isRasterDwgSource(data.m_resolvedType, data.m_recordName, data.m_className)) {
        retainRasterDwgPublication(data);
        return;
    }
    if (data.m_recordName == "PLOTSETTINGS"
        || data.m_className == "AcDbPlotSettings") {
        (void)retainDwgPlotSettingsPublication(data);
        return;
    }
    const bool blockControlCandidate =
        data.m_recordName == "BLOCK_CONTROL"
        || data.m_encodedType == DRW::DwgBlockControlObjectType
        || data.m_resolvedType == DRW::DwgBlockControlObjectType;
    if (blockControlCandidate) {
        const auto reject = [this]() {
            cData->m_dwgBlockControlCaptureFailed = true;
        };
        std::size_t estimate = sizeof(DRW_DwgFramePublication);
        if (data.m_carrier != DRW_DwgFramePublication::Carrier::Control
            || cData->sourceFormat != dx_source_format::DWG
            || data.m_version < DRW::AC1012 || data.m_version > DRW::AC1032
            || data.m_handle == 0u || data.m_handle == DRW::NoHandle
            || !data.m_hasSourceLocation
            || (data.m_sourceOffsetSpace
                    != DRW_DwgFrameOffsetSpace::PhysicalFile
                && data.m_sourceOffsetSpace
                    != DRW_DwgFrameOffsetSpace::DecodedBuffer)
            || data.m_encodedType != DRW::DwgBlockControlObjectType
            || data.m_resolvedType != DRW::DwgBlockControlObjectType
            || data.m_isEntity || data.m_isCustomClass
            || data.m_classStreamOrdinal.has_value()
            || data.m_recordName != "BLOCK_CONTROL"
            || !data.m_className.empty()
            || data.m_commonLinkEvidence
                != DRW_DwgCommonLinkEvidence::NotApplicable
            || data.m_numReactors < 0
            || static_cast<std::size_t>(data.m_numReactors)
                != data.m_reactorHandles.size()
            || data.m_controlHandles.size()
                > kMaxAdapterBasicTableRecords
            || cData->m_dwgBlockControlPublicationSeen
            || cData->m_dwgBlockControlCaptureFailed
            || !addVectorPayloadBytes(data.m_controlHandles, estimate)
            || !addVectorPayloadBytes(data.m_reactorHandles, estimate)
            || !addStringPayloadBytes(data.m_recordName, estimate)
            || estimate > kMaxDwgBlockControlPublicationBytes) {
            reject();
            return;
        }
        try {
            std::unordered_set<std::uint32_t> uniqueHandles;
            uniqueHandles.reserve(data.m_controlHandles.size());
            for (std::uint32_t handle : data.m_controlHandles) {
                if (handle == 0u || handle == DRW::NoHandle
                    || !uniqueHandles.insert(handle).second) {
                    reject();
                    return;
                }
            }
            cData->m_dwgBlockControlPublication = data;
            cData->m_dwgBlockControlGeneration = cData->importGeneration;
            cData->m_dwgBlockControlPublicationSeen = true;
        } catch (...) {
            reject();
        }
        return;
    }
    const bool layerControlCandidate =
        data.m_recordName == "LAYER_CONTROL"
        || data.m_encodedType == DRW::DwgLayerControlObjectType
        || data.m_resolvedType == DRW::DwgLayerControlObjectType;
    if (layerControlCandidate) {
        const auto reject = [this]() {
            cData->m_dwgLayerControlCaptureFailed = true;
        };
        std::size_t estimate = sizeof(DRW_DwgFramePublication);
        if (data.m_carrier != DRW_DwgFramePublication::Carrier::Control
            || cData->sourceFormat != dx_source_format::DWG
            || data.m_version < DRW::AC1012 || data.m_version > DRW::AC1032
            || data.m_handle == 0u || data.m_handle == DRW::NoHandle
            || !data.m_hasSourceLocation
            || (data.m_sourceOffsetSpace
                    != DRW_DwgFrameOffsetSpace::PhysicalFile
                && data.m_sourceOffsetSpace
                    != DRW_DwgFrameOffsetSpace::DecodedBuffer)
            || data.m_encodedType != DRW::DwgLayerControlObjectType
            || data.m_resolvedType != DRW::DwgLayerControlObjectType
            || data.m_isEntity || data.m_isCustomClass
            || data.m_classStreamOrdinal.has_value()
            || data.m_recordName != "LAYER_CONTROL"
            || !data.m_className.empty()
            || data.m_commonLinkEvidence
                != DRW_DwgCommonLinkEvidence::NotApplicable
            || data.m_controlHandles.size()
                > kMaxAdapterBasicTableRecords
            || data.m_xDictFlag > 1u
            || cData->m_dwgLayerControlPublicationSeen
            || cData->m_dwgLayerControlCaptureFailed
            || !addVectorPayloadBytes(data.m_controlHandles, estimate)
            || !addStringPayloadBytes(data.m_recordName, estimate)
            || estimate > kMaxDwgBlockControlPublicationBytes) {
            reject();
            return;
        }
        try {
            std::unordered_set<std::uint32_t> uniqueHandles;
            uniqueHandles.reserve(data.m_controlHandles.size());
            for (std::uint32_t handle : data.m_controlHandles) {
                if (handle == 0u || handle == DRW::NoHandle
                    || !uniqueHandles.insert(handle).second) {
                    reject();
                    return;
                }
            }
            cData->m_dwgLayerControlPublication = data;
            cData->m_dwgLayerControlGeneration = cData->importGeneration;
            cData->m_dwgLayerControlPublicationSeen = true;
        } catch (...) {
            reject();
        }
        return;
    }
    const bool ltypeControlCandidate =
        data.m_recordName == "LTYPE_CONTROL"
        || data.m_encodedType == DRW::DwgLTypeControlObjectType
        || data.m_resolvedType == DRW::DwgLTypeControlObjectType;
    if (ltypeControlCandidate) {
        const auto reject = [this]() {
            cData->m_dwgLtypeControlCaptureFailed = true;
        };
        std::size_t estimate = sizeof(DRW_DwgFramePublication);
        if (data.m_carrier != DRW_DwgFramePublication::Carrier::Control
            || cData->sourceFormat != dx_source_format::DWG
            || data.m_version < DRW::AC1012 || data.m_version > DRW::AC1032
            || data.m_handle == 0u || data.m_handle == DRW::NoHandle
            || !data.m_hasSourceLocation
            || (data.m_sourceOffsetSpace
                    != DRW_DwgFrameOffsetSpace::PhysicalFile
                && data.m_sourceOffsetSpace
                    != DRW_DwgFrameOffsetSpace::DecodedBuffer)
            || data.m_encodedType != DRW::DwgLTypeControlObjectType
            || data.m_resolvedType != DRW::DwgLTypeControlObjectType
            || data.m_isEntity || data.m_isCustomClass
            || data.m_classStreamOrdinal.has_value()
            || data.m_recordName != "LTYPE_CONTROL"
            || !data.m_className.empty()
            || data.m_commonLinkEvidence
                != DRW_DwgCommonLinkEvidence::NotApplicable
            || data.m_xDictFlag > 1u
            || data.m_controlHandles.size()
                > kMaxAdapterBasicTableRecords
            || cData->m_dwgLtypeControlPublicationSeen
            || cData->m_dwgLtypeControlCaptureFailed
            || !addVectorPayloadBytes(data.m_controlHandles, estimate)
            || !addStringPayloadBytes(data.m_recordName, estimate)
            || estimate > kMaxDwgBlockControlPublicationBytes) {
            reject();
            return;
        }
        try {
            std::unordered_set<std::uint32_t> uniqueHandles;
            uniqueHandles.reserve(data.m_controlHandles.size());
            for (std::uint32_t handle : data.m_controlHandles) {
                if (handle == 0u || handle == DRW::NoHandle
                    || !uniqueHandles.insert(handle).second) {
                    reject();
                    return;
                }
            }
            cData->m_dwgLtypeControlPublication = data;
            cData->m_dwgLtypeControlGeneration = cData->importGeneration;
            cData->m_dwgLtypeControlPublicationSeen = true;
        } catch (...) {
            reject();
        }
        return;
    }
    if (!isStandardDwgObjectType(data.m_resolvedType)
        || cData->m_standardDwgObjectCaptureFailed)
        return;
    const auto reject = [this]() { rejectStandardDwgObjectCapture(); };
    const auto found = cData->m_standardDwgObjectFrames.find(
        {cData->importGeneration, data.m_handle});
    if (found == cData->m_standardDwgObjectFrames.end()) {
        reject();
        return;
    }
    auto& frame = found->second;
    const auto& raw = frame.raw;
    const dx_data::StandardDwgOrdinalKey ordinal{
        cData->importGeneration, data.m_sourceMapOrdinal};
    const dx_data::StandardDwgLocationKey location{cData->importGeneration,
        {data.m_sourceOffsetSpace, data.m_sourceOffset}};
    const bool legacyUnknownLinks = raw.m_version <= DRW::AC1018
        && raw.m_commonLinkEvidence == DRW_DwgCommonLinkEvidence::Unknown;
    if (frame.publicationSeen || frame.generation != cData->importGeneration
        || data.m_isEntity || data.m_isCustomClass || data.m_classStreamOrdinal
        || data.m_carrier != DRW_DwgFramePublication::Carrier::TypedAndRaw
        || data.m_encodedType != raw.m_objectType || data.m_resolvedType != raw.m_objectType
        || data.m_recordName != raw.m_recordName || data.m_className != raw.m_className
        || data.m_version != raw.m_version || !data.m_hasSourceLocation
        || data.m_sourceOffset != raw.m_objectOffset
        || (data.m_sourceOffsetSpace != DRW_DwgFrameOffsetSpace::PhysicalFile
            && data.m_sourceOffsetSpace != DRW_DwgFrameOffsetSpace::DecodedBuffer)
        || data.m_commonLinkEvidence != raw.m_commonLinkEvidence
        || data.m_commonHandleDataValidated != raw.m_commonHandleDataValidated
        || data.m_numReactors < 0 || data.m_xDictFlag > 1
        // Legacy raw wrappers omit unverified common-link projections, while
        // publications can still carry the reactor count from the prologue.
        // Preserve both Unknown views; never treat their zeroes as absence.
        || (!legacyUnknownLinks
            && (data.m_parentHandle != raw.m_parentHandle
                || data.m_reactorHandles != raw.m_reactorHandles
                || data.m_numReactors != raw.m_numReactors
                || data.m_xDictHandle != raw.m_xDictHandle
                || data.m_xDictFlag != raw.m_xDictFlag))
        || !data.m_controlHandles.empty()
        || cData->m_standardDwgObjectOrdinals.count(ordinal) != 0u
        || cData->m_standardDwgObjectLocations.count(location) != 0u) {
        reject();
        return;
    }
    // The inline publication object is charged with the raw-frame slot;
    // charge its dynamic members and two source-identity index nodes here.
    std::size_t estimate = 0u;
    if (!addVectorPayloadBytes(data.m_reactorHandles, estimate)
        || !addStringPayloadBytes(data.m_recordName, estimate)
        || !addStringPayloadBytes(data.m_className, estimate)
        || !addAssociativeSlotBytes(1u,
            sizeof(std::pair<const dx_data::StandardDwgOrdinalKey, std::uint32_t>)
                + 4u * sizeof(void*), estimate)
        || !addAssociativeSlotBytes(1u,
            sizeof(std::pair<const dx_data::StandardDwgLocationKey, std::uint32_t>)
                + 4u * sizeof(void*), estimate)
        || !standardDwgCaptureFits(cData->m_standardDwgObjectRetainedBytes, estimate)) {
        reject();
        return;
    }
    try {
        frame.publication = data;
        cData->m_standardDwgObjectOrdinals.emplace(ordinal, data.m_handle);
        cData->m_standardDwgObjectLocations.emplace(location, data.m_handle);
        frame.publicationSeen = true;
        cData->m_standardDwgObjectRetainedBytes += estimate;
    } catch (...) {
        reject();
    }
}

void dx_iface::addDwgDictionaryMembership(const DRW_DwgDictionaryMembership& data) {
    if (cData == nullptr || !cData->dwgReadOutcome.attempted
        || cData->m_standardDwgObjectCaptureFailed)
        return;
    const auto reject = [this]() { rejectStandardDwgObjectCapture(); };
    const auto found = cData->m_standardDwgObjectFrames.find(
        {cData->importGeneration, data.m_dictionaryHandle});
    if (found == cData->m_standardDwgObjectFrames.end()) {
        reject();
        return;
    }
    auto& frame = found->second;
    if (frame.raw.m_objectType != dwgObjType::DICTIONARY
        || frame.generation != cData->importGeneration
        || !frame.publicationSeen || frame.membershipSeen || !data.m_complete
        || !sameStandardDwgSource(frame.publication, data.m_version,
            data.m_dictionaryHandle, data.m_sourceOffset, data.m_sourceMapOrdinal,
            data.m_sourceOffsetSpace, data.m_hasSourceLocation)
        || cData->m_standardDwgObjectMembershipEntries > StandardDwgObjectCaptureMaxEntries
        || data.m_entries.size() > StandardDwgObjectCaptureMaxEntries
            - cData->m_standardDwgObjectMembershipEntries) {
        reject();
        return;
    }
    std::size_t estimate = 0u;
    if (!addVectorPayloadBytes(data.m_entries, estimate)) {
        reject();
        return;
    }
    for (const auto& entry : data.m_entries) {
        // A complete DICTIONARY receipt can legitimately contain a null item
        // reference. One observed DWG profile also pairs that null reference
        // with an empty key. Retain that source pair faithfully; DXF output
        // admission still rejects empty dictionary keys and null references.
        if ((entry.m_name.empty() && entry.m_handle != 0u)
            || !addStringPayloadBytes(entry.m_name, estimate)) {
            reject();
            return;
        }
    }
    if (!standardDwgCaptureFits(cData->m_standardDwgObjectRetainedBytes, estimate)) {
        reject();
        return;
    }
    try {
        frame.dictionaryMembership = data;
        frame.membershipSeen = true;
        cData->m_standardDwgObjectMembershipEntries += data.m_entries.size();
        cData->m_standardDwgObjectRetainedBytes += estimate;
    } catch (...) {
        reject();
    }
}

void dx_iface::addDwgGroupMembership(const DRW_DwgGroupMembership& data) {
    if (cData == nullptr || !cData->dwgReadOutcome.attempted
        || cData->m_standardDwgObjectCaptureFailed)
        return;
    const auto reject = [this]() { rejectStandardDwgObjectCapture(); };
    const auto found = cData->m_standardDwgObjectFrames.find(
        {cData->importGeneration, data.m_groupHandle});
    if (found == cData->m_standardDwgObjectFrames.end()) {
        reject();
        return;
    }
    auto& frame = found->second;
    if (frame.raw.m_objectType != dwgObjType::GROUP
        || frame.generation != cData->importGeneration
        || !frame.publicationSeen || frame.membershipSeen || !data.m_complete
        || !sameStandardDwgSource(frame.publication, data.m_version,
            data.m_groupHandle, data.m_sourceOffset, data.m_sourceMapOrdinal,
            data.m_sourceOffsetSpace, data.m_hasSourceLocation)
        || cData->m_standardDwgObjectMembershipEntries > StandardDwgObjectCaptureMaxEntries
        || data.m_entries.size() > StandardDwgObjectCaptureMaxEntries
            - cData->m_standardDwgObjectMembershipEntries) {
        reject();
        return;
    }
    std::size_t estimate = 0u;
    if (!addVectorPayloadBytes(data.m_entries, estimate)
        || !standardDwgCaptureFits(cData->m_standardDwgObjectRetainedBytes, estimate)) {
        reject();
        return;
    }
    for (std::size_t ordinal = 0; ordinal < data.m_entries.size(); ++ordinal) {
        const auto& entry = data.m_entries[ordinal];
        if (entry.m_handle == 0 || entry.m_handle == DRW::NoHandle
            || entry.m_ordinal != ordinal) {
            reject();
            return;
        }
    }
    try {
        frame.groupMembership = data;
        frame.membershipSeen = true;
        cData->m_standardDwgObjectMembershipEntries += data.m_entries.size();
        cData->m_standardDwgObjectRetainedBytes += estimate;
    } catch (...) {
        reject();
    }
}

void dx_iface::finishStandardDwgObjectCapture(bool successfulRead) noexcept {
    if (cData == nullptr)
        return;
    cData->m_standardDwgNamesClosedThrough = std::max(
        cData->m_standardDwgNamesClosedThrough, cData->importGeneration);
    const auto currentBegin = cData->m_standardDwgObjectFrames.lower_bound(
        {cData->importGeneration, 0u});
    const bool hasCurrentFrames = currentBegin != cData->m_standardDwgObjectFrames.end()
        && currentBegin->first.first == cData->importGeneration;
    if (!successfulRead && hasCurrentFrames)
        rejectStandardDwgObjectCapture();
    if (cData->m_standardDwgObjectCaptureFailed) {
        rejectStandardDwgObjectCapture();
        return;
    }
    std::size_t matched = 0u;
    for (auto current = currentBegin;
         current != cData->m_standardDwgObjectFrames.end()
             && current->first.first == cData->importGeneration; ++current) {
        auto& frame = current->second;
        if (frame.generation != cData->importGeneration
            || frame.raw.m_version != cData->dwgReadOutcome.sourceVersion
            || !frame.publicationSeen
            || (frame.raw.m_objectType != dwgObjType::XRECORD && !frame.membershipSeen)) {
            rejectStandardDwgObjectCapture();
            return;
        }
        const auto& outcome = cData->dwgReadOutcome;
        if (frame.sourceProfileBound
            && (frame.sourceCodePageId != outcome.sourceCodePageId
                || frame.sourceCodePageFieldPresent != outcome.sourceCodePageFieldPresent
                || frame.sourceCodePageRecognized != outcome.sourceCodePageRecognized)) {
            rejectStandardDwgObjectCapture();
            return;
        }
        frame.sourceCodePageId = outcome.sourceCodePageId;
        frame.sourceCodePageFieldPresent = outcome.sourceCodePageFieldPresent;
        frame.sourceCodePageRecognized = outcome.sourceCodePageRecognized;
        frame.sourceProfileBound = true;
        ++matched;
    }
    // This records source-callback correlation only, not payload/typed equality
    // or proof that the output graph actually serializes the record.
    cData->dwgReadOutcome.standardObjectSourceReceiptsMatched =
        matched;
}

void dx_iface::validateStandardDwgObjectPayloads(
        const StandardDwgObjectImportRange& range) noexcept {
    if (cData == nullptr)
        return;
    const auto reject = [this]() noexcept {
        cData->m_standardDwgObjectPayloadFailed = true;
        cData->dwgReadOutcome.standardObjectPayloadValidationFailed = true;
        cData->dwgReadOutcome.standardObjectTypedPayloadsMatched = 0u;
        cData->dwgReadOutcome.standardObjectOpaquePayloadsMatched = 0u;
    };
    if (cData->m_standardDwgObjectPayloadFailed) {
        reject();
        return;
    }
    if (cData->m_standardDwgObjectCaptureFailed)
        return; // the distinct source-capture failure already refuses export
    const auto begin = cData->m_standardDwgObjectFrames.lower_bound(
        {cData->importGeneration, 0u});
    if (begin == cData->m_standardDwgObjectFrames.end()
        || begin->first.first != cData->importGeneration)
        return;
    try {
        std::map<std::uint32_t, const DRW_TableEntry*> typed;
        const auto retain = [this, &typed](const DRW_TableEntry& record) {
            const auto source = cData->m_standardDwgObjectFrames.find(
                {cData->importGeneration, record.handle});
            if (source == cData->m_standardDwgObjectFrames.end())
                return true; // e.g. a dynamically classified custom XRECORD
            return typed.emplace(record.handle, &record).second;
        };
        if (!standardDwgSuffix<DRW_Dictionary>(cData->dictionaries, range.dictionaryBegin, retain)
            || !standardDwgSuffix<DRW_Group>(cData->groups, range.groupBegin, retain)
            || !standardDwgSuffix<DRW_XRecord>(cData->xRecords, range.xRecordBegin, retain)
            || (cData->associativeDxfImport.namedObjectDictionaryCallbackSeen
                && (!cData->hasNamedObjectDictionary
                    || cData->associativeDxfImport.namedObjectDictionaryCallbackAmbiguous
                    || !retain(cData->namedObjectDictionary)))) {
            reject();
            return;
        }
        StandardDwgNameIndex appIds, layers;
        if (!standardDwgNames(cData->appIds, range.appIdBegin, appIds)
            || !standardDwgNames(cData->layers, range.layerBegin, layers)) {
            reject();
            return;
        }
        std::size_t matched = 0u, opaque = 0u;
        DRW_TextCodec codec;
        const dx_data::StandardDwgObjectFrame* codecProfile = nullptr;
        for (auto current = begin; current != cData->m_standardDwgObjectFrames.end()
             && current->first.first == cData->importGeneration; ++current) {
            auto& frame = current->second;
            const auto& raw = frame.raw;
            const auto found = typed.find(raw.m_handle);
            if (!frame.sourceProfileBound || !frame.publicationSeen
                || frame.generation != cData->importGeneration || found == typed.end()) {
                reject();
                return;
            }
            // Reuse one decoder for adjacent identical saved profiles rather
            // than rebuilding a multibyte converter for every source object.
            if (codecProfile == nullptr || codecProfile->raw.m_version != raw.m_version
                || codecProfile->sourceCodePageId != frame.sourceCodePageId
                || codecProfile->sourceCodePageFieldPresent != frame.sourceCodePageFieldPresent
                || codecProfile->sourceCodePageRecognized != frame.sourceCodePageRecognized) {
                DRW_TextCodec candidate;
                candidate.setVersion(raw.m_version, false);
                if (frame.sourceCodePageFieldPresent && frame.sourceCodePageRecognized) {
                    const char* name = dwgCodePageName(frame.sourceCodePageId);
                    if (name == nullptr) {
                        reject();
                        return;
                    }
                    candidate.setByteCodePage(name);
                    if (raw.m_version <= DRW::AC1018)
                        candidate.setCodePage(name, false);
                }
                candidate.swap(codec);
                codecProfile = &frame;
            }
            codec.resetAccumulatedDecodeIssues();
            dwgBuffer body(raw.m_rawBytes.data(), raw.m_rawBytes.size(), &codec);
            dwgBuffer typeProbe = body.forkIndependent();
            if (typeProbe.getObjType(raw.m_version) != raw.m_objectType
                || !typeProbe.isGood()) {
                reject();
                return;
            }
            std::vector<std::uint32_t> appIdDependencies;
            std::vector<std::uint64_t> layerDependencies;
            const auto observeAppId = [&](std::uint32_t handle, const UTF8STRING& name) {
                if (appIdDependencies.size() >= StandardDwgObjectCaptureMaxEntries)
                    return false;
                appIdDependencies.push_back(handle);
                const auto source = cData->m_standardDwgAppIdSources.find(
                    {frame.generation, handle});
                const auto unbound = DRW::dxfTextIssueMask(
                    DRW::DxfTextIssue::UnsupportedEncodingProfile);
                if (source == cData->m_standardDwgAppIdSources.end()) {
                    // Tolerant fallback/current rows are not source evidence.
                    codec.mergeDecodeIssues(unbound);
                    return true;
                }
                if (!source->second || source->second->name != name)
                    return false;
                const DRW_AppId& app = *source->second;
                codec.mergeDecodeIssues(app.dwgNameDecodeIssues());
                const char* page = raw.m_version > DRW::AC1018 ? "UTF-16"
                    : frame.sourceCodePageFieldPresent && frame.sourceCodePageRecognized
                        ? dwgCodePageName(frame.sourceCodePageId) : nullptr;
                if (!app.hasUnchangedDwgSourceName() || page == nullptr
                    || !app.hasBoundDwgNameProfile(raw.m_version, page))
                    codec.mergeDecodeIssues(unbound);
                if (raw.m_version <= DRW::AC1018 && page != nullptr
                    && dwgCodePageId(page) != frame.sourceCodePageId)
                    codec.mergeDecodeIssues(DRW::dxfTextIssueMask(
                        DRW::DxfTextIssue::CompatibilityCodePage));
                return true;
            };
            const auto observeLayer = [&](std::uint64_t handle, const UTF8STRING& name) {
                if (layerDependencies.size() >= StandardDwgObjectCaptureMaxEntries)
                    return false;
                layerDependencies.push_back(handle);
                const auto unbound = DRW::dxfTextIssueMask(DRW::DxfTextIssue::UnsupportedEncodingProfile);
                if (handle > (std::numeric_limits<std::uint32_t>::max)()) {
                    codec.mergeDecodeIssues(unbound);
                    return true;
                }
                const auto source = cData->m_standardDwgLayerSources.find(
                    {frame.generation, static_cast<std::uint32_t>(handle)});
                if (source == cData->m_standardDwgLayerSources.end()) {
                    codec.mergeDecodeIssues(unbound);
                    return true;
                }
                if (!source->second || source->second->name != name)
                    return false;
                const DRW_Layer& layer = *source->second;
                codec.mergeDecodeIssues(layer.dwgNameDecodeIssues());
                const char* page = raw.m_version > DRW::AC1018 ? "UTF-16"
                    : frame.sourceCodePageFieldPresent && frame.sourceCodePageRecognized
                        ? dwgCodePageName(frame.sourceCodePageId) : nullptr;
                if (!layer.hasUnchangedDwgSourceName() || page == nullptr
                    || !layer.hasBoundDwgNameProfile(raw.m_version, page))
                    codec.mergeDecodeIssues(unbound);
                if (raw.m_version <= DRW::AC1018 && page != nullptr
                    && dwgCodePageId(page) != frame.sourceCodePageId)
                    codec.mergeDecodeIssues(DRW::dxfTextIssueMask(DRW::DxfTextIssue::CompatibilityCodePage));
                return true;
            };
            const auto compareCommon = [&](DRW_TableEntry& parsed, bool compareName = true) {
                if (!resolveStandardDwgExtendedData(parsed, appIds, layers, observeAppId, observeLayer)
                    || !standardDwgCommonEqual(parsed, *found->second, raw.m_version, compareName)
                    || parsed.handle != raw.m_handle
                    || parsed.reactorCount() != frame.publication.m_numReactors
                    || parsed.extensionDictionaryFlag() != frame.publication.m_xDictFlag)
                    return false;
                // Unknown legacy projections remain Unknown. The parsed
                // common links are compared to the typed callback instead.
                return !drwDwgCommonLinkEvidenceValidated(raw.m_commonLinkEvidence)
                    || (parsed.parentHandle == raw.m_parentHandle
                        && parsed.reactorHandles == raw.m_reactorHandles
                        && parsed.xDictHandle == raw.m_xDictHandle);
            };
            bool equal = false, isOpaque = false;
            switch (raw.m_objectType) {
            case dwgObjType::DICTIONARY: {
                StandardDwgPayloadProbe<DRW_Dictionary> parsed;
                const auto* record = dynamic_cast<const DRW_Dictionary*>(found->second);
                equal = record != nullptr && record->tType == DRW::DICTIONARY
                    && parsed.parseDwg(raw.m_version, &body, raw.m_bodyBitSize)
                    && body.isGood() && compareCommon(parsed)
                    && parsed.hasCompleteDwgEntries() && record->hasCompleteDwgEntries()
                    && !parsed.countCap && !record->countCap
                    && parsed.cloning == record->cloning && parsed.hardOwner == record->hardOwner
                    && frame.membershipSeen && frame.dictionaryMembership.m_complete
                    && parsed.m_entries.size() == record->m_entries.size()
                    && parsed.m_entries.size() == frame.dictionaryMembership.m_entries.size();
                for (std::size_t index = 0; equal && index < parsed.m_entries.size(); ++index) {
                    const auto& a = parsed.m_entries[index];
                    const auto& b = record->m_entries[index];
                    const auto& receipt = frame.dictionaryMembership.m_entries[index];
                    equal = a.m_name == b.m_name && a.m_handle == b.m_handle
                        && a.m_dxfHandleCode == b.m_dxfHandleCode
                        && a.m_name == receipt.m_name && a.m_handle == receipt.m_handle;
                }
                break;
            }
            case dwgObjType::GROUP: {
                StandardDwgPayloadProbe<DRW_Group> parsed;
                const auto* record = dynamic_cast<const DRW_Group*>(found->second);
                equal = record != nullptr
                    && parsed.parseDwg(raw.m_version, &body, raw.m_bodyBitSize)
                    && body.isGood() && compareCommon(parsed, false)
                    && parsed.hasCompleteDwgEntityHandles() && record->hasCompleteDwgEntityHandles()
                    && parsed.m_description == record->m_description
                    && parsed.m_isUnnamed == record->m_isUnnamed
                    && parsed.m_selectable == record->m_selectable
                    && parsed.m_entityHandles == record->m_entityHandles
                    && frame.membershipSeen && frame.groupMembership.m_complete
                    && parsed.m_entityHandles.size() == frame.groupMembership.m_entries.size();
                for (std::size_t index = 0; equal && index < parsed.m_entityHandles.size(); ++index) {
                    const auto& receipt = frame.groupMembership.m_entries[index];
                    equal = parsed.m_entityHandles[index] == receipt.m_handle
                        && receipt.m_ordinal == index;
                }
                break;
            }
            case dwgObjType::XRECORD: {
                StandardDwgPayloadProbe<DRW_XRecord> parsed;
                const auto* record = dynamic_cast<const DRW_XRecord*>(found->second);
                equal = record != nullptr
                    && parsed.parseDwg(raw.m_version, &body, raw.m_bodyBitSize)
                    && body.isGood() && compareCommon(parsed)
                    && parsed.m_cloning == record->m_cloning
                    && parsed.m_handleValues == record->m_handleValues
                    && standardDwgValuesEqual(parsed.m_values, record->m_values, raw.m_version)
                    && standardDwgValuesEqual(parsed.m_dataEntries, record->m_dataEntries, raw.m_version)
                    && parsed.m_rawData == record->m_rawData
                    && parsed.m_rawDataValid == record->m_rawDataValid
                    && parsed.hasDwgRawDataSourceRecord() == record->hasDwgRawDataSourceRecord()
                    && parsed.dwgRawDataVersion() == record->dwgRawDataVersion()
                    && parsed.canReplayDwgRawData(raw.m_version) == record->canReplayDwgRawData(raw.m_version)
                    && parsed.hasExactDxfCoordinateTuples() == record->hasExactDxfCoordinateTuples();
                isOpaque = parsed.m_rawDataValid || parsed.hasDwgRawDataSourceRecord();
                break;
            }
            default:
                break;
            }
            if (!equal) {
                reject();
                return;
            }
            const auto textIssues = codec.accumulatedDecodeIssues();
            std::sort(appIdDependencies.begin(), appIdDependencies.end());
            appIdDependencies.erase(std::unique(appIdDependencies.begin(),
                appIdDependencies.end()), appIdDependencies.end());
            std::sort(layerDependencies.begin(), layerDependencies.end());
            layerDependencies.erase(std::unique(layerDependencies.begin(),
                layerDependencies.end()), layerDependencies.end());
            if (frame.typedBaseline) {
                // Revalidation cannot refresh provenance from edited consumer
                // state or a different latest-import dependency envelope.
                if (!frame.textDecodeObserved || frame.textDecodeIssues != textIssues
                    || frame.appIdDependencies != appIdDependencies
                    || frame.layerDependencies != layerDependencies
                    || !standardDwgModelsEqual(*frame.typedBaseline, *found->second,
                                             raw.m_version, raw.m_objectType)) {
                    reject();
                    return;
                }
            } else {
                std::size_t bytes = 0u, items = 0u;
                if (!estimateStandardDwgModelBytes(*found->second, raw.m_objectType,
                                                   bytes, items)
                    || !addVectorPayloadBytes(appIdDependencies, bytes)
                    || !addAssociativeRetainedBytes(appIdDependencies.size(), items)
                    || !addVectorPayloadBytes(layerDependencies, bytes)
                    || !addAssociativeRetainedBytes(layerDependencies.size(), items)
                    || !addAssociativeRetainedBytes(2u * sizeof(void*), bytes)
                    || !standardDwgCaptureFits(cData->m_standardDwgObjectRetainedBytes, bytes)
                    || cData->m_standardDwgObjectMembershipEntries > StandardDwgObjectCaptureMaxEntries
                    || items > StandardDwgObjectCaptureMaxEntries
                            - cData->m_standardDwgObjectMembershipEntries) {
                    reject();
                    return;
                }
                auto snapshot = copyStandardDwgModel(*found->second, raw.m_objectType);
                if (!snapshot || !standardDwgModelsEqual(*snapshot, *found->second,
                                                           raw.m_version, raw.m_objectType)) {
                    reject();
                    return;
                }
                frame.typedBaseline = std::move(snapshot);
                frame.textDecodeIssues = textIssues;
                frame.textDecodeObserved = true;
                frame.appIdDependencies = std::move(appIdDependencies);
                frame.layerDependencies = std::move(layerDependencies);
                cData->m_standardDwgObjectRetainedBytes += bytes;
                cData->m_standardDwgObjectMembershipEntries += items;
            }
            frame.payloadMatched = true;
            frame.opaquePayload = isOpaque;
            if (isOpaque)
                ++opaque;
            else
                ++matched;
        }
        // Counts publish only after every source matched. Neither count
        // contributes to opaque-retention or actual-output completeness.
        cData->dwgReadOutcome.standardObjectTypedPayloadsMatched = matched;
        cData->dwgReadOutcome.standardObjectOpaquePayloadsMatched = opaque;
    } catch (...) {
        reject();
    }
}

namespace {
bool sameVerifiedXRecordRaw(const DRW_UnsupportedObject& a,
                            const DRW_UnsupportedObject& b) noexcept {
    return a.m_objectType == b.m_objectType && a.m_handle == b.m_handle
        && a.m_parentHandle == b.m_parentHandle
        && a.m_commonHandleDataValidated == b.m_commonHandleDataValidated
        && a.m_commonLinkEvidence == b.m_commonLinkEvidence
        && a.m_reactorHandles == b.m_reactorHandles
        && a.m_xDictHandle == b.m_xDictHandle && a.m_numReactors == b.m_numReactors
        && a.m_xDictFlag == b.m_xDictFlag && a.m_blockOwnerHandle == b.m_blockOwnerHandle
        && a.m_bodyBitSize == b.m_bodyBitSize && a.m_objectOffset == b.m_objectOffset
        && a.m_objectSize == b.m_objectSize && a.m_isEntity == b.m_isEntity
        && a.m_isCustomClass == b.m_isCustomClass && a.m_recordName == b.m_recordName
        && a.m_className == b.m_className && a.m_rawBytes == b.m_rawBytes
        && a.m_typedPayloadValidated == b.m_typedPayloadValidated
        && a.m_version == b.m_version && a.m_hasDataStorage == b.m_hasDataStorage
        && a.m_hasClassDefinition == b.m_hasClassDefinition
        && a.m_classProxyFlag == b.m_classProxyFlag && a.m_classAppName == b.m_classAppName
        && a.m_classWasProxy == b.m_classWasProxy
        && a.m_classEntityFlagRaw == b.m_classEntityFlagRaw
        && a.m_classDwgVersion == b.m_classDwgVersion
        && a.m_classMaintenanceVersion == b.m_classMaintenanceVersion
        && a.m_classUnknown1 == b.m_classUnknown1 && a.m_classUnknown2 == b.m_classUnknown2;
}
bool sameVerifiedXRecordPublication(const DRW_DwgFramePublication& a,
                                    const DRW_DwgFramePublication& b) noexcept {
    return a.m_version == b.m_version && a.m_handle == b.m_handle
        && a.m_sourceOffset == b.m_sourceOffset && a.m_sourceMapOrdinal == b.m_sourceMapOrdinal
        && a.m_sourceOffsetSpace == b.m_sourceOffsetSpace && a.m_hasSourceLocation == b.m_hasSourceLocation
        && a.m_encodedType == b.m_encodedType && a.m_resolvedType == b.m_resolvedType
        && a.m_isEntity == b.m_isEntity && a.m_isCustomClass == b.m_isCustomClass
        && a.m_recordName == b.m_recordName && a.m_className == b.m_className
        && a.m_classStreamOrdinal == b.m_classStreamOrdinal
        && a.m_commonHandleDataValidated == b.m_commonHandleDataValidated
        && a.m_commonLinkEvidence == b.m_commonLinkEvidence && a.m_parentHandle == b.m_parentHandle
        && a.m_reactorHandles == b.m_reactorHandles && a.m_xDictHandle == b.m_xDictHandle
        && a.m_numReactors == b.m_numReactors && a.m_xDictFlag == b.m_xDictFlag
        && a.m_controlHandles == b.m_controlHandles && a.m_carrier == b.m_carrier;
}
}

bool dx_iface::enableVerifiedXRecordSources(const std::vector<std::uint32_t>& handles) noexcept {
    if (m_verifiedXRecordReadData || m_verifiedStyleControlSelected != 0u
        || m_verifiedLTypeControlSelected != 0u
        || handles.size()>64u) return false;
    try {
        auto selected=handles;
        std::sort(selected.begin(),selected.end());
        if (std::any_of(selected.cbegin(),selected.cend(),[](std::uint32_t h) {
                return h==0u || h==DRW::NoHandle;
            }) || std::adjacent_find(selected.cbegin(),selected.cend())!=selected.cend())
            return false;
        m_verifiedXRecordSelected.swap(selected);
        m_verifiedTableContentSelected=0u;m_verifiedDataTableSelected=0u;m_verifiedTableGeometrySelected=0u;
        m_verifiedTableRoundtripSelected=false;m_verifiedTableRoundtripChildrenSelected=false;
        m_verifiedTableEntitySelected=0u;m_verifiedTableDictionarySelected=0u;m_verifiedReciprocalTableSelected=false;m_verifiedTableModelSelected=false;m_verifiedTableProjectionSelected=false;m_verifiedTableStyleSelected=0u;
        m_verifiedStyleDictionarySelected=0u;m_verifiedStyleXRecordSelected=0u;m_verifiedCellStyleMapSelected=0u;m_verifiedStyleXRecordRequired=false;m_verifiedCellStyleMapRequired=false;
        return true;
    } catch (...) { return false; }
}

bool dx_iface::enableVerifiedStyleResourceSource(
        std::uint32_t styleControl, std::uint32_t styleRecord) noexcept {
    if (m_verifiedXRecordReadData || !m_verifiedXRecordSelected.empty()
        || m_verifiedLTypeControlSelected != 0u
        || m_verifiedTableContentSelected != 0u || m_verifiedDataTableSelected != 0u
        || styleControl == 0u || styleControl == DRW::NoHandle
        || styleRecord == 0u || styleRecord == DRW::NoHandle
        || styleControl == styleRecord)
        return false;
    m_verifiedStyleControlSelected = styleControl;
    m_verifiedStyleRecordSelected = styleRecord;
    return true;
}

bool dx_iface::enableVerifiedLTypeResourceSource(
        std::uint32_t controlHandle, std::uint32_t ordinaryHandle,
        std::uint32_t byBlockHandle, std::uint32_t byLayerHandle) noexcept {
    if (m_verifiedXRecordReadData || !m_verifiedXRecordSelected.empty()
        || m_verifiedTableContentSelected != 0u
        || m_verifiedTableGeometrySelected != 0u
        || m_verifiedTableStyleSelected != 0u
        || m_verifiedTableEntitySelected != 0u
        || m_verifiedTableDictionarySelected != 0u
        || m_verifiedStyleDictionarySelected != 0u
        || m_verifiedStyleXRecordSelected != 0u
        || m_verifiedCellStyleMapSelected != 0u
        || m_verifiedStyleControlSelected != 0u
        || m_verifiedStyleRecordSelected != 0u
        || m_verifiedLTypeControlSelected != 0u
        || m_verifiedReciprocalTableSelected
        || m_verifiedTableModelSelected
        || m_verifiedTableProjectionSelected
        || controlHandle == 0u || controlHandle == DRW::NoHandle
        || ordinaryHandle == 0u || ordinaryHandle == DRW::NoHandle
        || byBlockHandle == 0u || byBlockHandle == DRW::NoHandle
        || byLayerHandle == 0u || byLayerHandle == DRW::NoHandle
        || controlHandle == ordinaryHandle || controlHandle == byBlockHandle
        || controlHandle == byLayerHandle || ordinaryHandle == byBlockHandle
        || ordinaryHandle == byLayerHandle || byBlockHandle == byLayerHandle)
        return false;
    m_verifiedLTypeControlSelected = controlHandle;
    m_verifiedLTypeOrdinarySelected = ordinaryHandle;
    m_verifiedLTypeByBlockSelected = byBlockHandle;
    m_verifiedLTypeByLayerSelected = byLayerHandle;
    return true;
}

bool dx_iface::enableVerifiedTableCandidates(const std::vector<std::uint32_t>& xrecords,
        std::uint32_t tableContent,std::uint32_t dataTable) noexcept {
    if (m_verifiedXRecordReadData || m_verifiedStyleControlSelected != 0u
        || m_verifiedLTypeControlSelected != 0u
        || xrecords.empty() || xrecords.size()>64u
        || tableContent==0u || tableContent==DRW::NoHandle
        || dataTable==0u || dataTable==DRW::NoHandle || tableContent==dataTable) return false;
    try {
        auto selected=xrecords;
        std::sort(selected.begin(),selected.end());
        if (std::any_of(selected.cbegin(),selected.cend(),[&](std::uint32_t h) {
                return h==0u || h==DRW::NoHandle || h==tableContent || h==dataTable;
            }) || std::adjacent_find(selected.cbegin(),selected.cend())!=selected.cend()) return false;
        m_verifiedXRecordSelected.swap(selected);
        m_verifiedTableContentSelected=tableContent;m_verifiedDataTableSelected=dataTable;
        m_verifiedTableGeometrySelected=0u;m_verifiedTableRoundtripSelected=false;m_verifiedTableRoundtripChildrenSelected=false;
        m_verifiedTableEntitySelected=0u;m_verifiedTableDictionarySelected=0u;m_verifiedReciprocalTableSelected=false;m_verifiedTableModelSelected=false;m_verifiedTableProjectionSelected=false;m_verifiedTableStyleSelected=0u;
        m_verifiedStyleDictionarySelected=0u;m_verifiedStyleXRecordSelected=0u;m_verifiedCellStyleMapSelected=0u;m_verifiedStyleXRecordRequired=false;m_verifiedCellStyleMapRequired=false;
        return true;
    } catch (...) {return false;}
}

bool dx_iface::enableVerifiedTableCandidates(const std::vector<std::uint32_t>& xrecords,
        std::uint32_t tableContent,std::uint32_t dataTable,std::uint32_t tableGeometry) noexcept {
    if (m_verifiedXRecordReadData || m_verifiedLTypeControlSelected != 0u
        || xrecords.empty() || xrecords.size()>64u
        || tableContent==0u || tableContent==DRW::NoHandle
        || dataTable==0u || dataTable==DRW::NoHandle
        || tableGeometry==0u || tableGeometry==DRW::NoHandle
        || tableContent==dataTable || tableContent==tableGeometry || dataTable==tableGeometry) return false;
    try {
        auto selected=xrecords;std::sort(selected.begin(),selected.end());
        if (std::any_of(selected.cbegin(),selected.cend(),[&](std::uint32_t h) {
                return h==0u || h==DRW::NoHandle || h==tableContent || h==dataTable || h==tableGeometry;
            }) || std::adjacent_find(selected.cbegin(),selected.cend())!=selected.cend()) return false;
        m_verifiedXRecordSelected.swap(selected);
        m_verifiedTableContentSelected=tableContent;m_verifiedDataTableSelected=dataTable;
        m_verifiedTableGeometrySelected=tableGeometry;m_verifiedTableRoundtripSelected=false;m_verifiedTableRoundtripChildrenSelected=false;
        m_verifiedTableEntitySelected=0u;m_verifiedTableDictionarySelected=0u;m_verifiedReciprocalTableSelected=false;m_verifiedTableModelSelected=false;m_verifiedTableProjectionSelected=false;m_verifiedTableStyleSelected=0u;
        m_verifiedStyleDictionarySelected=0u;m_verifiedStyleXRecordSelected=0u;m_verifiedCellStyleMapSelected=0u;m_verifiedStyleXRecordRequired=false;m_verifiedCellStyleMapRequired=false;
        return true;
    } catch (...) {return false;}
}

bool dx_iface::enableVerifiedTableRoundtripCandidates(const std::vector<std::uint32_t>& xrecords,
        std::uint32_t tableContent,std::uint32_t dataTable,std::uint32_t tableGeometry) noexcept {
    if (!enableVerifiedTableCandidates(xrecords,tableContent,dataTable,tableGeometry)) return false;
    m_verifiedTableRoundtripSelected=true;
    return true;
}

bool dx_iface::enableVerifiedTableRoundtripChildren(const std::vector<std::uint32_t>& xrecords,
        std::uint32_t tableContent,std::uint32_t dataTable,std::uint32_t tableGeometry) noexcept {
    if (xrecords.size()!=10u || !enableVerifiedTableRoundtripCandidates(xrecords,tableContent,dataTable,tableGeometry))return false;
    m_verifiedTableRoundtripChildrenSelected=true;
    return true;
}

bool dx_iface::enableVerifiedTableExtensionDictionary(const std::vector<std::uint32_t>& xrecords,
        std::uint32_t content,std::uint32_t table,std::uint32_t geometry,
        std::uint32_t entity,std::uint32_t dictionary) noexcept {
    if(!entity || entity==DRW::NoHandle || !dictionary || dictionary==DRW::NoHandle
        || entity==dictionary || entity==content || entity==table || entity==geometry
        || dictionary==content || dictionary==table || dictionary==geometry
        || std::find(xrecords.cbegin(),xrecords.cend(),entity)!=xrecords.cend()
        || std::find(xrecords.cbegin(),xrecords.cend(),dictionary)!=xrecords.cend())return false;
    if(!enableVerifiedTableRoundtripChildren(xrecords,content,table,geometry))return false;
    m_verifiedTableEntitySelected=entity;m_verifiedTableDictionarySelected=dictionary;return true;
}

